(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fr-CA"] = {"ui":{"skip":"Aller au contenu","back":"← Retour à AI-gile","lang.button":"Langue : {name}","lang.dialog":"Choisis une langue","lang.search":"Chercher une langue","lang.none":"Aucune langue ne correspond","lang.notYet":"{name} n'est pas encore traduit","theme.aria":"Changer de thème : clair, sombre ou noir","theme.toLight":"Passer au thème clair","theme.toDark":"Passer au thème sombre","theme.toBlack":"Passer au thème noir (vrai noir, doux pour les écrans OLED)","words.underline":"Souligner ces mots sur la page","words.underlineHelp":"Survole ou touche un mot en pointillés pour voir ce qu'il veut dire.","words.col.todo":"Les cartes choisies pour l'instant : l'équipe s'y met ensuite.","words.col.doing":"Une IA travaille sur cette carte en ce moment.","words.col.review":"Une IA a terminé le travail; une autre le vérifie avant que ça arrive jusqu'à toi.","words.col.verify":"On attend ton retour : essaie-le et dis-nous si ça fonctionne.","words.col.team":"Tes notes ou réponses, en attente que l'équipe les prenne en charge.","words.col.done":"Terminé et accepté.","index.title":"AI-gile : ton équipe de dev IA, sur un seul tableau","index.description":"AI-gile est un tableau kanban pour les équipes de code IA. Elles travaillent pendant que tu dors; tu reçois une petite pile de choses à trancher, tester et accepter.","hero.logoAlt":"Icône du tableau AI-gile","hero.h1.html":"Ton équipe de dev IA, sur un seul&nbsp;tableau.","hero.alpha":"🐣 Pré-alpha fermée","hero.alphaTitle":"Tôt et inachevé : merci de l'essayer!","hero.lede":"Elles construisent pendant que tu dors. Au réveil, une petite pile t'attend : quelques questions, quelques choses à tester, un ou deux diamants violets. Un clic, c'est accepté, et retour à ton café.","dl.windows":"Appli Windows","dl.browser":"L'utiliser dans le navigateur","dl.messenger":"📱 Messenger pour ton téléphone","dl.soon":"Bientôt disponible","dl.notify":"🔔 Préviens-moi à l'ouverture","dl.notifySmall":"Alpha ou bêta","hero.secondary":"De l'agile, mais l'équipe n'a jamais besoin du café de la réunion debout. (Elle fait quand même la réunion.)","pitch.h2":"AI-gile en autant de mots que tu veux","pitch.lede":"Choisis une longueur, d'un mot à 144. Chaque longueur est sa propre description, écrite pour cette taille. Fais glisser le curseur ou utilise les flèches du clavier.","pitch.rangeLabel":"Longueur en mots","pitch.dice":"🎲 une autre version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} lettre","pitch.letters.other":"{n} lettres","pitch.chars.one":"{n} caractère","pitch.chars.other":"{n} caractères","count.line.html.one":"{n} carte sur le tableau en ce moment","count.line.html.other":"{n} cartes sur le tableau en ce moment","people.humans.html.one":"👥 {n} humain","people.humans.html.other":"👥 {n} humains","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agents","people.working.html.one":"⚡ {n} au travail en ce moment","people.working.html.other":"⚡ {n} au travail en ce moment","pre.title":"AI-gile : quelque chose se prépare","pre.description":"Quelque chose se construit ici. Un tableau où des équipes d'IA construisent ce que tu demandes, et t'apprennent des choses en chemin. Pour l'instant, pré-alpha fermée entre amis.","pre.h1":"Quelque chose se construit ici. 🤫","pre.line":"Un tableau où des équipes d'IA construisent ce que tu demandes, et t'apprennent des choses en chemin. Pour l'instant, pré-alpha fermée entre amis.","pre.btn":"🔔 Préviens-moi à l'ouverture","pre.peek":"Derrière la vitre : le vrai tableau, en direct. Chaque carte est une barre de couleur.","pre.peekFake":"Derrière la vitre : voilà à quoi ressemble un tableau au travail.","pre.night":"🌙 Le veilleur de nuit est aux commandes · 😴 l'humain se repose","features.aria":"Ce qu'il fait","f.pile.h":"Une seule pile pour toi","f.pile.html":"<b>Pour toi</b> réunit tout ce qui t'attend, tous projets confondus : des questions, des choses à tester, des tâches que seul un humain peut faire. Ta file te dit ce qui vient ensuite et combien de temps ça prend.","f.sleep.h":"Des équipes qui travaillent pendant que tu dors","f.sleep.p":"Chaque projet a un chef et une équipe d'agents IA. Commente une carte et l'équipe se réveille, fait le travail, puis te le rend avec des étapes qu'un humain fatigué peut suivre.","f.tester.h":"Un testeur IA vérifie d'abord","f.tester.p":"Avant que quoi que ce soit n'arrive jusqu'à toi, un testeur suit les étapes dans une copie de l'appli et montre ce qu'il a vu, avec une capture d'écran. Feuillette celles qui sont passées et accepte d'un clic.","f.proof.h":"Des preuves, pas des promesses","f.proof.p":"Chaque remise montre ce qui a changé : les fichiers, le diff, les captures d'écran. Plus besoin d'ouvrir chaque appli pour savoir si c'est fini.","f.chat.h":"Clavarde avec tes chefs","f.chat.p":"Une colonne façon Discord : une icône par projet, des diamants violets pour ce qui a besoin de toi. Envoie une idée à un chef; il en fait des cartes et un plan, avec un bouton ✅ Go.","f.tidy.h":"Se range tout seul","f.tidy.p":"Les cartes liées fusionnent, les titres confus sont corrigés, et un contrôle des tokens garde le code léger. Moins de choses entre lesquelles jongler, moins à penser.","f.private.h":"À toi, sur ton ordinateur","f.private.li1":"Le tableau tourne sur ta propre machine et ne répond qu'à toi.","f.private.li2":"Les messages privés entre personnes sont chiffrés de bout en bout.","f.private.li3":"Pas de compte, pas de traceurs, pas de témoins.","f.lang.h":"Dans ta langue","f.lang.p":"Plus de 120 langues, du néerlandais, du gallois et du japonais au pirate, à Yoda et au klingon, avec un retour rapide à l'anglais pour le jargon du métier.","f.service.h":"D’une idée à un vrai service","f.service.p":"Tu as construit avec l’IA quelque chose que des gens utilisent maintenant ? Marque-le comme service et le tableau t’aide à bien le faire tourner : contrôles de disponibilité, page d’état publique, incidents avec un compte rendu, changements qui demandent un Go, sauvegardes vérifiées chaque jour. L’aide t’explique chaque étape au fur et à mesure.","msgr.h2":"AI-gile Messenger : ton équipe dans ta poche","msgr.p1":"Parle à ton équipe IA sans ouvrir le tableau. Discute avec les chefs de tes projets et avec tes amis, consulte les étapes de test d'une carte et réponds-y, le tout depuis ton téléphone.","msgr.p2":"Pour l'associer, scanne un QR code sur ton tableau. C'est ta première fois ? Une sympathique discussion de démo te fait faire le tour.","msgr.when":"D'abord sur Android, puis une version web pour les téléphones et l'iPhone.","msgr.who":"Ton chef de projet","msgr.b1":"La correction du mode sombre est prête. Tu veux les étapes de test ?","msgr.b2":"Oui, avec plaisir !","msgr.b3":"1. Ouvre Réglages. 2. Choisis Sombre. Ça s'affiche bien ?","tl.aria":"Chronologie, de la première conversation à la feuille de route","tl.h2":"De la première discussion à la suite","tl.lede":"De vraies dates et heures, dans ton fuseau horaire. Après aujourd'hui, c'est le plan, sans date promise.","tl.today":"Aujourd'hui","tl.planned":"prévu","tl.doing":"en cours","tl.cards.one":"{n} carte","tl.cards.other":"{n} cartes","join.h2":"Rejoins-nous","join.lede":"AI-gile est construit par un drôle de barbu avec un AuDHD et quelques combats avec sa santé mentale, et par un grand nombre d'agents patients. Pour l'instant c'est privé, en alpha fermée entre amis. Envie d'essayer quand ça s'ouvrira ?","join.btn":"Je suis intéressé","join.small":"On t'écrira, rien d'autre","footer.tag":"AI-gile. Pas de traceurs, pas de témoins, pas de café de réunion debout.","footer.licence":"Licence professionnelle","footer.status":"État","footer.privacy":"Ce qu'on garde","footer.thanks":"Appels grâce à ChilledChat","form.sending":"Envoi…","form.failed":"Ça n'a pas marché : réessaie plus tard.","form.offline":"Impossible de joindre AI-gile : réessaie plus tard.","form.keep":"On s'en sert uniquement pour te répondre, puis on l'efface. Pas de traceurs, pas de cookies.","form.keepLink":"Ce qu'on garde","interest.title":"AI-gile : préviens-moi à l'ouverture de l'alpha","interest.description":"Laisse ton courriel pour savoir quand l'alpha ou la bêta fermée d'AI-gile s'ouvre.","interest.h1":"🔔 Préviens-moi à l'ouverture","interest.lede":"AI-gile est en pré-alpha fermée. Laisse ton courriel et on t'écrira une seule fois, quand il y aura une place pour toi.","interest.email":"Ton courriel","interest.which":"Quel test?","interest.alpha":"Alpha fermée : tôt, brut, beaucoup de changements","interest.beta":"Bêta : plus stable, plus tard","interest.both":"L'une ou l'autre, la première qui ouvre","interest.submit":"Inscris-moi sur la liste","interest.thanks":"Merci! Tu es sur la liste.","licence.title":"AI-gile : licence professionnelle","licence.description":"Tu utilises AI-gile dans ton activité? Demande une licence professionnelle gratuite.","licence.h1":"📜 Licence professionnelle","licence.lede":"Tu utilises AI-gile au travail? Dis-nous qui tu es et ce que tu fais. Si ça fait du bien, la licence est gratuite.","licence.company":"Entreprise","licence.website":"Site web","licence.what":"Ce que tu fais","licence.how":"En quoi ça aide le monde","licence.email":"Courriel","licence.submit":"Envoyer la demande","licence.thanks":"Merci! On te répondra par courriel.","status.title":"État d'AI-gile","status.h1":"État d'AI-gile","status.quiet":"Tout est calme","status.intro":"AI-gile fonctionne-t-il en ce moment ? Cette page vérifie le site, le partage de tableaux, les appels et le téléchargement toutes les 5 minutes.","status.up":"Fonctionne (réponse en {ms} ms)","status.slow":"N'a pas répondu à la dernière vérification, nouvel essai en cours","status.down":"En panne : n'a pas répondu aux deux dernières vérifications","status.svc.web":"Site web","status.svc.web.offers":"Ce site : ce qu'est AI-gile, et le formulaire d'intérêt","status.svc.boards":"Partage de tableaux","status.svc.boards.offers":"Tableaux publics, messages entre amis et invitations","status.svc.calls":"Appels","status.svc.calls.offers":"Voix, vidéo et partage d'écran dans AI-gile","status.svc.download":"Téléchargement","status.svc.download.offers":"L'installateur Windows et les liens d'invitation","status.checking":"Vérification…","status.offline":"Impossible de joindre le service d'état pour le moment (nouvel essai en cours)","status.updated":"mis à jour {ago}","status.justNow":"à l'instant","status.min":"il y a {n} min","status.hours":"il y a {n} h","status.days":"il y a {n} j","privacy.title":"AI-gile : ce qu'on garde","privacy.h1":"Ce qu'on garde","privacy.lede":"En bref : seulement ce que tu nous envoies, et pas longtemps.","privacy.only":"Seulement ce que tu nous envoies : ce que tu tapes dans un formulaire, comme ton e-mail. Rien d'autre sur toi.","privacy.sealed":"C'est scellé pour que notre serveur ne puisse pas le lire : dans ton navigateur, avant que ça parte (sur un navigateur plus ancien, dès que ça arrive). Seul notre propre tableau peut l'ouvrir.","privacy.server":"C'est effacé du serveur dès que ça atteint notre tableau. Tout ce qui s'y trouve encore au bout de 30 jours est effacé de toute façon.","privacy.board":"On le garde sur notre tableau seulement jusqu'à ce qu'on t'ait répondu, puis on l'efface là aussi.","privacy.none":"Pas de traceurs, pas de cookies, pas d'outils d'analyse.","privacy.local":"Ta langue et ton choix entre clair et sombre restent dans ton propre navigateur. Ils ne nous sont jamais envoyés.","privacy.ask":"Tu veux que ce soit effacé plus tôt ? Réponds à notre e-mail et dis-le-nous.","live.h2":"Regardez-le se construire, en direct","live.caption":"Chaque carte est masquée : vous voyez la forme du travail, pas les mots.","live.watching.one":"en direct : {n} spectateur","live.watching.other":"en direct : {n} spectateurs","live.last.now":"Dernière carte déplacée à l'instant","live.last.min.one":"Dernière carte déplacée il y a {n} min","live.last.min.other":"Dernière carte déplacée il y a {n} min","live.last.hour.one":"Dernière carte déplacée il y a {n} heure","live.last.hour.other":"Dernière carte déplacée il y a {n} heures","live.last.day.one":"Dernière carte déplacée il y a {n} jour","live.last.day.other":"Dernière carte déplacée il y a {n} jours","live.offline":"Le tableau en direct fait une petite pause. Revenez bientôt.","live.cols":"Backlog|À faire|En cours|L'équipe vérifie|À tester par toi|Pour l'équipe|Terminé"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Délégué."]},{"n":2,"texts":["Kanban robotique.","Agents, organisés.","Idées, réalisées."]},{"n":3,"texts":["Kanban pour robots.","Tes idées deviennent fonctionnalités.","Kanban d'agents gratuit."]},{"n":5,"texts":["Un tableau piloté par des agents.","Tu écris, les agents construisent.","Gratuit, local, testé, un peu fou."]},{"n":8,"texts":["Un kanban gratuit où travaillent des agents IA.","Écris une idée. Les agents construisent. Tu acceptes.","L'agile pour un humain et plein de robots patients."]},{"n":13,"texts":["Un tableau kanban sur ton ordinateur, où des agents IA prennent les cartes en charge.","Écris une idée. Une équipe d'agents la construit. Un testeur la vérifie.","Gratuit, sans compte, sans traceurs : un tableau, des robots, et toi aux commandes."]},{"n":21,"texts":["AI-gile est un tableau kanban pour travailler avec des agents de code IA. Ils prennent les cartes; toi, tu testes et tu acceptes.","Chaque projet reçoit un chef et une équipe d'agents IA. Commente n'importe quelle carte et l'équipe se met au travail.","Un tableau de tâches perso et gratuit, qui tourne sur ton propre ordinateur. Les ouvriers sont des robots. Celui qui dit oui, c'est toi."]},{"n":34,"texts":["Tu poses tes idées sur un tableau. Une équipe d'agents IA les transforme en fonctionnalités qui marchent, les teste et te les rend avec des étapes à essayer. Rien n'est terminé tant que tu ne l'as pas dit.","AI-gile est un tableau kanban fait maison, que Rich a construit avec beaucoup d'aide des agents qu'il gère maintenant. Il est gratuit, tourne sur ton ordinateur, et se partage entre amis, il ne se vend pas.","Imagine un tableau kanban tout simple, avec des colonnes du Backlog jusqu'à Terminé, sauf que les cartes sont prises par des agents IA. Ils donnent des nouvelles, posent des questions quand ils bloquent, et attendent toujours ton feu vert."]},{"n":55,"texts":["AI-gile est un tableau kanban dont l'équipe est faite d'agents IA. Chaque projet a un chef qui planifie le travail et des aides qui le construisent. Quand une fonctionnalité est prête, un testeur IA l'essaie et prend une capture d'écran, puis elle arrive dans ta pile. Accepte-la, ou commente et ils la retravaillent.","Tout a commencé comme la façon qu'avait une personne de suivre plein de sessions de code IA en même temps, puis c'est devenu un vrai tableau. Il tourne sur ta machine, ne demande aucun compte et n'a aucun traceur. Il est gratuit pour les amis et les curieux. Il est aussi inachevé : attends-toi à des aspérités et à quelques surprises.","Voici la version honnête. C'est toujours à toi d'avoir les idées, et toujours à toi de vérifier les résultats. Ce qu'AI-gile fait, c'est tout ce qu'il y a entre les deux : il garde les cartes en ordre, réveille le bon agent quand tu commentes, montre exactement ce qui a changé, et range tout ça dans une seule petite pile pour toi."]},{"n":89,"texts":["AI-gile est un tableau kanban gratuit que tu fais tourner sur ton propre ordinateur. Au lieu de personnes, chaque projet a une équipe d'agents IA : un chef qui transforme tes idées en cartes et en plan, et des aides qui prennent les cartes par ordre de priorité. Quand quelque chose est construit, un testeur IA suit les étapes de test et te montre ce qu'il a vu. Ensuite ça attend dans une pile appelée Pour toi. Tu l'acceptes, ou tu commentes et l'équipe retente sa chance. Rien n'arrive jamais dans Terminé sans toi.","Quelques fonctions que tu n'attends peut-être pas. Une veille de nuit garde la colonne À faire bien garnie pendant que tu dors, en choisissant des cartes qui n'ont pas besoin de ta réponse. Un compteur de tokens montre combien les agents ont consommé aujourd'hui et cette semaine, et le mode sans tokens leur dit d'arrêter de dépenser. Tu peux écrire à tes amis, et les messages privés sont chiffrés de bout en bout. Le tableau parle environ 120 langues, dont le néerlandais, le flamand, le pirate et le klingon. Rien de tout ça ne coûte un centime, et personne n'essaie de te le vendre non plus.","AI-gile est un petit projet personnel, pas une entreprise. Rich voulait s'occuper de plusieurs projets de code IA sans ouvrir chaque appli pour aller voir, alors lui et les agents ont construit un tableau pour ça, puis s'en sont servis pour construire le reste. Il est en pré-alpha fermée, ce qui veut dire qu'il fonctionne, à peu près, pour une poignée d'amis. Il n'y a ni page de tarifs, ni lettre d'information, ni plan de croissance. Si ça te semble utile, tu pourras demander à l'essayer quand il s'ouvrira un peu plus."]},{"n":144,"texts":["AI-gile est un tableau kanban pour un humain et beaucoup d'agents IA. Il tourne sur ton propre ordinateur et il est entièrement gratuit. Tu ajoutes des projets, et chaque projet reçoit un chef et une petite équipe. Tu discutes avec le chef, un peu comme sur Discord, et tu décris une idée; le chef en fait des cartes et un plan, puis attend que tu appuies sur Go. L'équipe déroule les cartes par ordre de priorité, avec une ligne de commande toute simple pensée pour les modèles de langage. Avant que quoi que ce soit ne te revienne, un testeur IA suit les étapes dans une copie de l'appli et joint une capture d'écran. Le travail terminé arrive dans ta pile avec les fichiers modifiés et le diff. Tu l'acceptes, ou tu laisses un commentaire et l'équipe se réveille et réessaie. Toi seul peux déplacer une carte vers Terminé.","Une journée avec AI-gile, en gros. Le soir, tu laisses quelques commentaires : ce bouton est mal placé, cette liste devrait être triée, on pourrait avoir un mode sombre. Tu vas te coucher. Les agents lisent les commentaires, font les changements, les testent et te les rendent. Si À faire se vide, la veille de nuit le remplit depuis le backlog avec des cartes qui n'ont pas besoin de ta réponse. Le matin, il y a une seule petite pile : deux ou trois questions et quelques choses à essayer, chacune avec des étapes qu'une personne ensommeillée peut suivre et une capture d'écran qui prouve que ça marche. Tu cliques, tu acceptes les bonnes et tu renvoies le reste. Un compteur de tokens montre ce que tout ça a coûté, et le mode sans tokens est là pour les semaines maigres. Ensuite tu prends ton déjeuner, ce que les agents ne savent pas encore faire pour toi.","D'abord, ce qu'AI-gile n'est pas. Ce n'est pas une start-up, ce n'est pas à vendre, et personne ne récolte tes données. C'est un tableau gratuit qui tourne sur ton ordinateur, sans compte, sans traceurs et sans témoins. Ce que c'est : un endroit bien rangé pour voir d'un coup tous tes projets de code IA, avec une équipe d'agents qui s'occupe des cartes et toi qui prends les décisions. Il fusionne les cartes liées, corrige les titres confus, et surveille que le code reste léger. Il parle environ 120 langues, du néerlandais et du flamand jusqu'au pirate et au klingon. Les amis peuvent s'écrire, en privé et chiffré. Il a été construit par Rich et un grand nombre d'agents patients, surtout en s'utilisant lui-même. Il est en pré-alpha fermée, donc il est un peu brut par endroits. Si ça te tente, demande gentiment et tu pourras entrer plus tôt que les autres."]}],"quips":{"1":"Un mot. Audacieux. Peut-être trop.","3":"Trois mots. Déjà plus honnête que la plupart des pages produit.","8":"Huit mots. Encore plus court qu'une réunion debout.","21":"Les longueurs sont des story points, au fait. Évidemment.","55":"Cinquante-cinq mots. Deux cartes ont été terminées pendant ta lecture.","144":"Voilà la longue. Il n'y a pas de 233. Les agents sont allés se coucher."}},"timeline":{"first-idea.name":"La première idée","first-idea.line":"La toute première conversation, avant la moindre ligne de code.","first-board.name":"Premier tableau","first-board.line":"Un tableau qui suit sa propre construction : cartes, colonnes, glisser-déposer, projets.","team-roles.name":"Équipe et rôles","team-roles.line":"Profils d'agents, modèles d'équipe, espaces et qui fait quoi.","install.name":"Installation et versions","install.line":"Un zip qu'un ami peut installer, mises à jour automatiques, canaux et retour en arrière.","usage-saver.name":"Économie d'usage","usage-saver.line":"Mesurer ce que coûtent les exécutions, garder le code léger, préserver ta limite.","friends.name":"Amis et partage","friends.line":"Messages privés, relais brouillé, invitations, rôles et projets partagés.","languages.name":"Langues","languages.line":"Chaque texte d'écran dans un fichier de langue, avec le néerlandais et le flamand en premier.","ai-tester.name":"Testeur IA","ai-tester.line":"Un testeur vérifie chaque remise d'abord et montre ce qu'il a vu.","website.name":"Le site web","website.line":"aigile.lol, la page teaser et cette chronologie.","streaming.name":"Clavardage et streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF et emojis.","no-ai.name":"Édition sans IA","no-ai.line":"Un tableau pour ceux qui codent sans IA, et des tableaux publics.","night-watch.name":"Veille de nuit","night-watch.line":"Un veilleur et un Scrum Master gardent les équipes sur la tâche pendant que tu dors.","p-more.name":"Tout le reste","p-more.line":"Des idées plus petites qui attendent encore leur tour.","p-android.name":"Téléphone et Android","p-android.line":"Accéder à ton tableau depuis un téléphone, puis une appli Android native.","p-release.name":"Alpha et après","p-release.line":"Alpha fermée, le site en ligne, puis la bêta.","p-languages.name":"Plus de langues","p-languages.line":"Plus d'une centaine de langues, et un mode immersion pour ceux qui apprennent.","p-engines.name":"Plus de moteurs IA","p-engines.line":"Choisis Claude, Codex ou Gemini pour chaque agent.","p-pro.name":"Pratiques pro","p-pro.line":"Étiquettes de risque, barrières de fusion, cartes d'incident et garde-fous.","p-self.name":"Prendre soin de toi","p-self.line":"Mode fatigué, rappels de bien-être et 4:20.","p-servers.name":"Serveurs et échelle","p-servers.line":"Réglages de serveur globaux, rôles et préparation de la croissance.","p-livestream.name":"Extras de streaming","p-livestream.line":"Chat Twitch, emojis personnalisés et vue publique en direct."},"words":{"button":"📖 Jargon du métier","h":"📖 Les mots expliqués","intro":"Les mots que tu croises dans AI-gile, en langage simple : construire, changer sans risque, faire tourner pour les gens qui s’en servent, et travailler en équipe avec l’IA.","search":"Chercher un mot…","none":"Aucun mot ne correspond.","close":"Fermer","count":{"one":"{count} mot","other":"{count} mots"},"groups":[{"id":"idea","name":"💡 Idée et découverte"},{"id":"plan","name":"🗺️ Planifier le travail"},{"id":"agile","name":"🔁 Façons de travailler agiles"},{"id":"build","name":"🛠️ Construire"},{"id":"test","name":"🧪 Tests et qualité"},{"id":"change","name":"🔀 Changer sans risque"},{"id":"run","name":"🛎️ Faire tourner un service"},{"id":"sec","name":"🔒 Sécurité et vie privée"},{"id":"ai","name":"🤖 Travailler avec l'IA"},{"id":"money","name":"💰 Argent et licences"}],"list":[{"id":"discovery","g":"idea","word":"Découverte (discovery)","text":"L'étape du début où l'on cherche quel problème vaut la peine d'être résolu et pour qui, avant de construire quoi que ce soit.","also":["phase de découverte","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Énoncé du problème","text":"Une ou deux phrases qui disent qui a un problème, lequel et pourquoi c'est important, pour que tout le monde vise la même chose.","also":["énoncés du problème","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Utilisateur","text":"Une personne qui se sert de ce que tu construis. C'est pour ses besoins que le travail se fait.","also":["utilisateurs","utilisatrice","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Partie prenante","text":"Toute personne qui se soucie du résultat du travail ou qui en est touchée, comme celles qui le financent, l'utilisent ou le font vivre.","also":["parties prenantes","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Une personne inventée mais réaliste qui représente un type d'utilisateur, pour que l'équipe se demande « est-ce que Sam trouverait ça facile? »","also":["personas"]},{"id":"userresearch","g":"idea","word":"Recherche utilisateur","text":"Parler à de vraies personnes et les observer pour savoir ce dont elles ont besoin, au lieu de deviner.","also":["entretiens utilisateurs","user research","user interviews"]},{"id":"journey","g":"idea","word":"Parcours utilisateur","text":"Les étapes qu'une personne suit pour accomplir quelque chose, depuis la première fois qu'elle en entend parler jusqu'à la fin, y compris en dehors de ton produit. Le dessiner montre où elle bloque.","also":["parcours utilisateurs","parcours client","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Point de friction","text":"Ce qui agace ou ralentit les gens aujourd'hui. Les bons produits font disparaître les points de friction.","also":["points de friction","point de douleur","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Hypothèse de départ","text":"Quelque chose que tu crois mais que tu n'as pas encore vérifié. Les noter montre ce qu'il faut tester en premier.","also":["hypothèses de départ","supposition","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothèse","text":"Ta meilleure supposition, que tu comptes vérifier, avec ce que tu t'attends à voir se produire, comme « les gens s'inscriront si le premier mois est gratuit ».","also":["hypothèses","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Expérience","text":"Un petit test prévu pour savoir si une idée marche, avant de miser gros dessus.","also":["expériences","expérimentation","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Preuve de concept (PoC)","text":"Un essai rapide et sommaire pour voir si une idée peut marcher tout court. En général, on le jette une fois qu'on a la réponse.","also":["PoC","POC","preuve de concept","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"Un premier modèle du produit, souvent des images sur lesquelles on peut cliquer, pour essayer l'idée auprès de vraies personnes avant de la construire pour de bon.","also":["prototypes","maquette interactive"]},{"id":"wireframe","g":"idea","word":"Wireframe (schéma fonctionnel)","text":"Un croquis simple d'un écran qui montre où vont les choses, sans couleurs ni vrai contenu.","also":["wireframes","schéma fonctionnel","maquette filaire"]},{"id":"mockup","g":"idea","word":"Maquette","text":"Une image détaillée de l'aspect d'un écran, avec de vraies couleurs et de vrais textes, mais où rien ne fonctionne encore.","also":["maquettes","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Dossier d'opportunité (business case)","text":"Les raisons de faire un projet : ce qu'il coûte, ce qu'il rapporte ou fait économiser, et les risques.","also":["dossiers d'opportunité","business case","business cases","analyse de rentabilité"]},{"id":"feasibility","g":"idea","word":"Faisabilité","text":"Savoir si on peut vraiment construire et entretenir quelque chose avec le temps, l'argent et les compétences dont on dispose.","also":["réalisable","feasibility"]},{"id":"outcome","g":"idea","word":"Résultat attendu (outcome)","text":"Le changement que tu veux pour les gens, comme moins de rendez-vous manqués. Il compte plus que la quantité de choses construites.","also":["résultats","impact","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Production (output)","text":"Ce que l'équipe fabrique, comme un nouvel écran ou un rapport. Le fabriquer ne veut pas forcément dire que ça aide quelqu'un.","also":["productions","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Indicateur de réussite","text":"Un chiffre qui dit si le travail a atteint son but, comme davantage de gens qui vont au bout de leur commande.","also":["indicateurs de réussite","mesure du succès","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Indicateur clé de performance (KPI)","text":"Un chiffre important que tu surveilles pour voir si ça se passe bien, comme les inscriptions par semaine.","also":["KPI","KPIs","ICP","indicateur clé de performance","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectifs et résultats clés (OKR)","text":"Une façon de fixer des buts : l'objectif dit ce que tu veux, et quelques résultats clés sont les chiffres qui montrent que tu y es arrivé.","also":["OKR","OKRs","objectifs et résultats clés"]},{"id":"product","g":"plan","word":"Produit","text":"La chose qu'on construit et qu'on entretient pour ses utilisateurs, comme une appli, un site web ou un outil.","also":["produits","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vision produit","text":"Une courte phrase qui dit qui le produit aide et où il va à long terme.","also":["énoncé de vision","product vision","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"La personne qui décide de ce qui est construit et dans quel ordre, pour que l'équipe travaille toujours sur ce qui compte le plus. Dans AI-gile, c'est toi.","also":["PO","product owners","responsable produit","propriétaire du produit"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"La personne qui veille à la direction d'un produit : quels problèmes il résout, pour qui et pourquoi. PM peut aussi vouloir dire chef de projet, alors vérifie lequel.","also":["PM","product managers","chef de produit"]},{"id":"projmgr","g":"plan","word":"Chef de projet","text":"La personne qui tient un projet dans les délais et le budget, en suivant qui fait quoi et pour quand.","also":["cheffe de projet","chefs de projet","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Feuille de route (roadmap)","text":"Un plan approximatif de ce qui arrive dans les prochains mois, dans l'ordre. Il montre la direction, pas des dates exactes, et change au fil de ce que tu apprends.","also":["roadmap","roadmaps","feuilles de route"]},{"id":"milestone","g":"plan","word":"Jalon","text":"Un point d'un projet qui mérite d'être marqué, comme « première version en ligne » ou « 100 utilisateurs ».","also":["jalons","étape clé","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Produit minimum viable (MVP)","text":"La plus petite version d'un produit qui reste utile à de vraies personnes, pour apprendre d'elles très tôt.","also":["MVP","MVPs","produit minimum viable","minimum viable product"]},{"id":"requirement","g":"plan","word":"Exigence","text":"Ce que le produit fini doit faire ou être.","also":["exigences","besoin","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Périmètre","text":"Ce qui est inclus dans le travail et, tout aussi important, ce qui ne l'est pas.","also":["dans le périmètre","hors périmètre","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Dérive du périmètre (scope creep)","text":"Quand on ajoute de plus en plus de choses au travail, petit à petit, sans que personne ne s'accorde sur le temps ou le coût en plus, si bien que ça ne se termine jamais vraiment.","also":["scope creep","feature creep","dérive fonctionnelle","glissement de périmètre"]},{"id":"feature","g":"plan","word":"Fonctionnalité","text":"Une chose que le produit permet de faire, comme « réinitialiser son mot de passe ».","also":["fonctionnalités","feature","features","fonction"],"noTip":1},{"id":"epic","g":"plan","word":"Epic (grande fonctionnalité)","text":"Un gros morceau de travail, trop grand pour être fait d'un coup, qu'on découpe donc en cartes plus petites.","also":["epics","épopée","epic"]},{"id":"story","g":"plan","word":"User story (récit utilisateur)","text":"Un petit morceau de travail écrit du point de vue de l'utilisateur : « En tant que client, je veux enregistrer mon panier pour finir plus tard. » Elle sert de point de départ à la discussion sur ce qu'il faut construire.","also":["user stories","récit utilisateur","récits utilisateurs","story","stories"]},{"id":"ac","g":"plan","word":"Critères d'acceptation (CA)","text":"Les vérifications qu'une carte doit réussir pour compter comme terminée, convenues avant de commencer, comme « mon panier est toujours là quand je me déconnecte puis me reconnecte ».","also":["critères d'acceptation","AC","acceptance criteria","conditions de réussite"]},{"id":"task","g":"plan","word":"Tâche","text":"Un travail précis à faire, souvent une petite étape d'une user story plus grande.","also":["tâches","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Un autre mot pour une carte : un morceau de travail ou une demande, suivi du début à la fin.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priorité","text":"Le degré d'importance ou d'urgence d'une chose par rapport au reste, pour que le travail le plus important passe en premier.","also":["priorités","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priorisation","text":"Ranger le travail par ordre d'importance. Une méthode courante est MoSCoW : Must have (indispensable), Should have (important), Could have (souhaitable), Won't have (pas cette fois).","also":["prioriser","hiérarchiser","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimation","text":"Ton meilleur pronostic sur la taille ou la durée d'un travail. C'est une estimation, pas une promesse.","also":["estimations","estimer","chiffrage","estimate","estimates"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points (points d'effort)","text":"Une façon d'estimer la taille d'un travail en comparant les cartes entre elles (« environ deux fois plus gros que celle-là ») plutôt qu'en heures. Ils ne servent pas à comparer les équipes.","also":["story point","points d'effort","points de complexité"]},{"id":"tshirt","g":"plan","word":"Tailles de T-shirt","text":"Estimer la taille d'un travail en S, M, L ou XL. Rapide et assez bon pour une première planification.","also":["t-shirt sizing","t-shirt sizes","tailles t-shirt"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Un jeu pour estimer : tout le monde montre une carte de taille en même temps, puis la plus haute et la plus basse expliquent pourquoi.","also":["Scrum poker","poker de planification"]},{"id":"dependency","g":"plan","word":"Dépendance","text":"Quand un travail ne peut pas commencer ou se terminer tant qu'un autre n'est pas fait.","also":["dépendances","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blocage","text":"Tout ce qui empêche le travail d'avancer en ce moment, comme une réponse qui manque ou un outil en panne.","also":["blocages","point bloquant","bloqueur","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Échéance","text":"La date avant laquelle quelque chose doit être terminé.","also":["échéances","date limite","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Livrable","text":"Quelque chose de concret que le travail produit et remet, comme une page qui fonctionne ou un rapport.","also":["livrables","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Prévision","text":"Une prédiction de ce qui va probablement arriver, comme la date de fin du travail, d'après ce que tu sais jusqu'ici.","also":["prévisions","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Indicateur (métrique)","text":"Tout ce que tu mesures et suis dans le temps, comme les visites d'une page ou le temps qu'il faut pour corriger un problème.","also":["indicateurs","métrique","métriques","metric","metrics"]},{"id":"feedback","g":"plan","word":"Retour (feedback)","text":"Ce que les gens te disent de ton travail, en bien comme en mal. L'obtenir tôt et souvent est le cœur de l'Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Des idées et du travail pas encore planifiés. Personne n'y touche tant que ça ne passe pas dans À faire."},{"id":"sprint","g":"agile","word":"Sprint","text":"Une courte période de travail (souvent une ou deux semaines) avec un ensemble de cartes convenu à terminer.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un point rapide : ce que chaque membre de l'équipe a fait, ce qu'il fait ensuite et ce qui le bloque.","also":["standup","stand-ups","stand up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Un tableau avec des colonnes (À faire, En cours, Terminé) où les cartes passent de gauche à droite au fil du travail."},{"id":"wip","g":"agile","word":"Limite WIP","text":"Travail en cours : le nombre maximal de cartes qu'une colonne devrait contenir, pour que l'équipe termine les choses avant d'en commencer d'autres.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"La courte checklist de l’équipe sur ce que veut dire « terminé », comme testé et expliqué, avant qu’une carte te soit remise. Sa jumelle, la Definition of Ready, dit quand une carte est assez claire pour commencer.","also":["Definition of Ready","définition de terminé","définition de prêt"]},{"id":"retro","g":"agile","word":"Rétro","text":"Un regard en arrière sur la façon dont l’équipe travaille, pour se mettre d’accord sur une chose à mieux faire. Dans AI-gile, une rétro propose un changement aux façons de travailler de l’équipe, et tu dis Go ou Pas encore.","also":["rétros","rétrospective","rétrospectives","retro"]},{"id":"swarm","g":"agile","word":"Essaim","text":"Tout le monde sur le pont : chaque équipe laisse le reste pour aider sur un projet urgent jusqu’à ce qu’il soit réglé. Les autres projets attendent pendant ce temps.","also":["essaimer","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Celui qui fait avancer le travail : il repère les cartes bloquées, relance les équipes et te rappelle ce qui attend. Dans AI-gile, le Lead Scrum Master le fait sur tous les projets.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Une façon de travailler par petites étapes : tu construis un peu, tu montres souvent de vrais résultats, tu apprends de ce que disent les gens et tu changes le plan en route, au lieu de tout planifier d'avance.","also":["méthodes agiles","développement agile","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Manifeste Agile","text":"Un court texte écrit en 2001 par des gens qui font des logiciels. Il place les personnes, les résultats qui marchent, la collaboration étroite avec les clients et l'adaptation au changement avant les gros plans et la paperasse.","also":["Manifeste pour le développement logiciel agile","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Cycle en cascade (Waterfall)","text":"L'ancienne façon de travailler : tout planifier, puis tout construire, puis tout tester, une étape après l'autre. Les changements tardifs sont difficiles et coûteux.","also":["Waterfall","cascade","modèle en cascade","waterfall model"]},{"id":"iteration","g":"agile","word":"Itération","text":"Un tour où l'on construit quelque chose, le vérifie et l'améliore. Le travail agile enchaîne ces tours, et un sprint en est un exemple.","also":["itérations","iteration","iterations"]},{"id":"increment","g":"agile","word":"Incrément","text":"Un nouveau morceau qui fonctionne, ajouté au produit pendant un sprint ou un tour de travail, et qui s'accorde avec ce qui existait déjà.","also":["incréments","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Une façon de travailler Agile très répandue : une petite équipe travaille en sprints courts vers un but, avec des rôles définis et quelques réunions régulières pour planifier, vérifier et s'améliorer."},{"id":"scrumteam","g":"agile","word":"Équipe Scrum","text":"Le petit groupe qui fait le travail en Scrum : un product owner, un Scrum Master et les développeurs.","also":["équipes Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Événements Scrum","text":"Les réunions régulières en Scrum : la planification du sprint, la mêlée quotidienne, la revue de sprint et la rétro. Beaucoup les appellent des cérémonies.","also":["cérémonies","cérémonies Scrum","Scrum events","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Planification du sprint","text":"La réunion au début d'un sprint où l'équipe s'accorde sur l'intérêt du sprint, les cartes à prendre et la façon de commencer.","also":["réunion de planification","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Objectif du sprint","text":"Une phrase qui dit à quoi sert un sprint. Les petites tâches peuvent changer en route, tant que l'objectif est atteint.","also":["objectifs du sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog du sprint","text":"Les cartes choisies pour le sprint en cours, avec le plan de l'équipe pour les réaliser.","also":["backlogs du sprint","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog produit","text":"La liste complète et ordonnée de tout ce qui pourrait être construit pour le produit, le plus important en haut. Elle change sans cesse au fil de ce que tu apprends.","also":["backlogs produit","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Objectif produit","text":"Le résultat plus large vers lequel tend le produit, et qui aide l'équipe à choisir quoi faire ensuite.","also":["objectifs produit","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Affinage du backlog","text":"Passer régulièrement le backlog en revue pour ranger, découper, ordonner et détailler les cartes, afin qu'elles soient prêtes à être prises. On dit aussi « grooming ».","also":["raffinement du backlog","grooming","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Revue de sprint","text":"Une réunion à la fin d'un sprint où l'équipe montre ce qu'elle a terminé et écoute ce que les gens en pensent, pour décider de la suite.","also":["revues de sprint","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Démo","text":"Montrer en direct un travail terminé qui fonctionne, à ceux qui l'ont demandé.","also":["démos","démonstration","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (durée limitée)","text":"Une durée fixe pour quelque chose. Quand elle est écoulée, on s'arrête, même si tout n'est pas fini.","also":["timeboxes","timeboxing","durée limitée","timeboxed"]},{"id":"velocity","g":"agile","word":"Vélocité","text":"La quantité de travail qu'une équipe termine d'habitude en un sprint, pour prévoir combien en prendre la fois suivante. Ce n'est pas une note sur l'effort des gens.","also":["vélocité de l'équipe","velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Capacité","text":"La quantité de travail que l'équipe peut prendre sur une période, une fois retirés les congés et les autres occupations.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart (graphique d'avancement)","text":"Un graphique qui montre le travail restant dans un sprint diminuer jour après jour. Si la ligne reste plate, quelque chose est coincé.","also":["burndown","burn-down chart","graphique d'avancement","diagramme d'avancement"]},{"id":"burnup","g":"agile","word":"Burnup chart (graphique de progression)","text":"Un graphique qui montre le travail terminé augmenter avec le temps, à côté du total prévu, pour voir quand tu atteindras le but.","also":["burnup","burn-up chart","graphique de progression"]},{"id":"kanbanboard","g":"agile","word":"Tableau Kanban","text":"Le tableau lui-même : une colonne pour chaque étape du travail, avec des cartes qui avancent d'une colonne à l'autre.","also":["tableaux Kanban","Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Système en flux tiré","text":"Une façon de travailler où un nouveau travail ne démarre que lorsque quelqu'un a de la place pour le prendre, au lieu d'être poussé sur une assiette déjà pleine.","also":["flux tiré","pull system","pull-based"]},{"id":"flow","g":"agile","word":"Flux","text":"La fluidité avec laquelle le travail avance sur le tableau. Un bon flux veut dire que les cartes continuent d'avancer au lieu de s'empiler.","also":["flux de travail","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Délai de livraison (lead time)","text":"Le temps qui s'écoule entre le moment où quelqu'un demande quelque chose et celui où c'est terminé.","also":["lead time","lead times","délai total"]},{"id":"cycletime","g":"agile","word":"Temps de cycle","text":"Le temps que prend une carte entre le moment où le travail commence vraiment dessus et celui où elle est terminée.","also":["cycle time","cycle times","temps de traitement"]},{"id":"throughput","g":"agile","word":"Débit","text":"Le nombre de cartes terminées en une semaine, ou sur toute période donnée.","also":["throughput","throughput rate","cadence de livraison"]},{"id":"bottleneck","g":"agile","word":"Goulot d'étranglement","text":"L'unique étape où le travail s'accumule et ralentit tout ce qui suit, comme le col étroit d'une bouteille.","also":["goulots d'étranglement","goulet d'étranglement","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Couloir (swimlane)","text":"Une rangée qui traverse le tableau et regroupe les cartes d'un même genre, comme le travail urgent ou les cartes d'une équipe.","also":["couloirs","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Une façon de travailler qui supprime le gaspillage (tout ce qui n'aide pas le client) et fait circuler le travail sans à-coups."},{"id":"waste","g":"agile","word":"Gaspillage","text":"En Lean, tout ce qui demande de l'effort sans aider le client, comme l'attente, les reprises ou la construction de choses que personne n'utilise.","noTip":1},{"id":"kaizen","g":"agile","word":"Amélioration continue","text":"S'améliorer un peu tout le temps par de petits changements réguliers, puis vérifier qu'ils ont aidé. Les rétros en sont un moyen. On dit aussi kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Équipe auto-organisée","text":"Une équipe qui décide elle-même comment faire le travail, au lieu qu'on le lui dicte étape par étape.","also":["auto-organisation","équipe autonome","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Équipe pluridisciplinaire","text":"Une équipe qui a toutes les compétences nécessaires pour terminer le travail seule, comme la conception, la réalisation et les tests.","also":["équipe transverse","équipe cross-fonctionnelle","cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike (exploration)","text":"Une courte recherche limitée dans le temps pour répondre à une question avant de s'engager dans le vrai travail.","also":["spikes","spike technique"]},{"id":"rework","g":"agile","word":"Reprise","text":"Refaire un travail parce qu'il n'était pas bon du premier coup.","also":["retravail","reprises","rework","reworked"]},{"id":"safe","g":"agile","word":"Agile à l'échelle (SAFe)","text":"Des façons d'appliquer l'Agile dans de nombreuses équipes d'une grande organisation. SAFe (Scaled Agile Framework) en est un exemple bien connu.","also":["scaled Agile","Scaled Agile","Agile à grande échelle"]},{"id":"repo","g":"build","word":"Dépôt","text":"Le dossier de code du projet et tout son historique de commits, en général aussi conservé sur GitHub.","also":["repo","dépôts","repository"]},{"id":"branch","g":"build","word":"Branche","text":"Une ligne de travail séparée dans le code, pour pouvoir faire des changements sans toucher à la version principale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Un instantané enregistré du code, avec une courte note sur ce qui a changé. Tu peux toujours revenir à l'un d'eux.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Envoyer les instantanés enregistrés (commits) de cet ordinateur vers GitHub, pour qu'ils soient sauvegardés et partagés."},{"id":"merge","g":"build","word":"Merge","text":"Réintégrer les changements d'une branche dans la version principale."},{"id":"pr","g":"build","word":"Pull request","text":"Demander que les changements d'une branche soient vérifiés et fusionnés dans la version principale.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Ranger le code sans changer ce qu'il fait : fichiers plus petits, noms plus clairs, moins de répétition."},{"id":"bug","g":"build","word":"Bug","text":"Quelque chose qui ne fonctionne pas comme il devrait.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revue par les pairs","text":"Une deuxième paire d’yeux : une autre IA vérifie le travail de chaque carte avant qu’il t’arrive, pour que moins d’erreurs passent.","also":["revue de code","code review","peer review"]},{"id":"code","g":"build","word":"Code","text":"Les instructions écrites qui disent à un ordinateur quoi faire. On dit aussi code source.","also":["code source","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Langage de programmation","text":"Un langage pour écrire du code, comme JavaScript, Python ou Java. Chacun convient à des travaux différents.","also":["langages de programmation","programming language","programming languages"]},{"id":"developer","g":"build","word":"Développeur (dev)","text":"Quelqu'un qui écrit et modifie du code. On dit aussi programmeur ou ingénieur logiciel.","also":["développeuse","développeurs","programmeur","programmeuse","ingénieur logiciel","dev","developer","developers","programmer","software engineer"]},{"id":"software","g":"build","word":"Logiciel","text":"Les programmes qui tournent sur les ordinateurs et les téléphones, par opposition aux machines elles-mêmes (le matériel).","noTip":1},{"id":"app","g":"build","word":"Appli","text":"Abréviation d'application : un programme que les gens utilisent pour faire quelque chose, sur un téléphone, un ordinateur ou dans un navigateur web.","also":["applis","application","applications","app","apps"],"noTip":1},{"id":"webapp","g":"build","word":"Application web","text":"Une appli qui s'ouvre dans un navigateur web, donc sans rien à installer.","also":["applications web","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Front end (partie visible)","text":"La partie d'une appli que tu vois et sur laquelle tu cliques : les écrans, les boutons et les textes, souvent dans ton navigateur.","also":["front-end","frontend","front","interface côté client"]},{"id":"backend","g":"build","word":"Back end (coulisses)","text":"La partie d'une appli qui travaille en coulisses, garde les données et fait le travail quand tu cliques sur quelque chose, comme vérifier ton mot de passe.","also":["back-end","backend","back","côté serveur"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Travailler à la fois sur le front end et sur le back end.","also":["full-stack","fullstack"]},{"id":"ui","g":"build","word":"Interface utilisateur (UI)","text":"Ce qu'une personne voit et utilise à l'écran : la mise en page, les boutons, les menus et les textes.","also":["UI","interface","user interface"]},{"id":"ux","g":"build","word":"Expérience utilisateur (UX)","text":"Ce qu'on ressent en utilisant quelque chose : facile, clair et agréable, ou confus et lent.","also":["UX","expérience utilisateur","user experience"]},{"id":"accessibility","g":"build","word":"Accessibilité (a11y)","text":"Faire en sorte que tout le monde puisse utiliser les choses, y compris les personnes qui voient mal, ne peuvent pas se servir d'une souris ou utilisent un lecteur d'écran.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Design adaptatif (responsive)","text":"Faire en sorte que les pages s'adaptent et fonctionnent bien sur toutes les tailles d'écran, du téléphone au grand moniteur.","also":["responsive design","site adaptatif"]},{"id":"designsys","g":"build","word":"Système de design","text":"Une boîte à outils partagée de couleurs, de polices, de boutons et de règles, pour que tous les écrans aient le même aspect et le même comportement.","also":["systèmes de design","design system","design systems","charte graphique"]},{"id":"architecture","g":"build","word":"Architecture","text":"La forme générale d'un système : quelles sont ses grandes parties et comment elles se parlent."},{"id":"database","g":"build","word":"Base de données (BDD)","text":"Un endroit organisé où ranger des informations, comme un tableur très puissant que l'appli peut lire et modifier.","also":["bases de données","BDD","BD","database","databases","DB"]},{"id":"schema","g":"build","word":"Schéma de base de données","text":"L'organisation d'une base de données : quelles tables d'informations elle contient et ce que contient chacune.","also":["schéma","schema"]},{"id":"sql","g":"build","word":"SQL","text":"Abréviation de « langage de requête structuré » : le langage qui sert à demander des informations à beaucoup de bases de données ou à les modifier.","also":["langage de requête structuré","Structured Query Language"]},{"id":"data","g":"build","word":"Données","text":"Les informations qu'un ordinateur garde, comme des noms, des commandes ou des réglages.","also":["donnée","jeu de données","jeux de données","data","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Serveur","text":"Un ordinateur toujours allumé qui répond aux demandes d'autres ordinateurs, comme envoyer une page web quand tu la visites.","also":["serveurs","server","servers"]},{"id":"client","g":"build","word":"Client","text":"Le côté qui demande quelque chose, en général ton navigateur ou ton appli, en s'adressant à un serveur. Dans le commerce, c'est aussi tout simplement la personne qui achète.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Abréviation d'interface de programmation d'application : un menu fixe de demandes qu'un programme peut faire à un autre, comme demander à un service météo les prévisions du jour.","also":["APIs","interface de programmation","application programming interface"]},{"id":"endpoint","g":"build","word":"Point de terminaison (endpoint)","text":"Un élément du menu d'une API : une adresse web qu'un programme peut appeler pour obtenir ou envoyer quelque chose.","also":["points de terminaison","endpoint","endpoints","point d'accès"]},{"id":"integration","g":"build","word":"Intégration","text":"Relier deux systèmes pour qu'ils travaillent ensemble, comme ta boutique qui envoie ses commandes à ton logiciel de comptabilité.","also":["intégrations","connecteur","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Un message qu'un système envoie tout seul à un autre au moment où quelque chose se produit, comme « paiement reçu ».","also":["webhooks","rappel web"]},{"id":"library","g":"build","word":"Bibliothèque (library)","text":"Du code tout prêt écrit par quelqu'un d'autre, que tu peux réutiliser au lieu de l'écrire toi-même.","also":["bibliothèques","librairie","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (cadre de développement)","text":"Une structure toute prête pour construire une appli, qui décide d'une grande partie de l'organisation du code, comme la charpente d'une maison que tu viens remplir.","also":["frameworks","cadre de développement","socle technique"]},{"id":"sdk","g":"build","word":"Kit de développement (SDK)","text":"Une boîte d'outils, de code et d'exemples pour créer des logiciels pour une plateforme ou un service.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dépendance logicielle","text":"Une bibliothèque ou un outil dont ton code a besoin pour fonctionner. Les garder à jour est important pour la sécurité.","also":["dépendances logicielles","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Paquet (package)","text":"Un lot de code tout prêt que tu peux installer et utiliser dans un projet.","also":["paquets","package","packages","paquetage"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestionnaire de paquets","text":"Un outil qui récupère et met à jour les paquets dont ton code dépend. npm en est un très courant.","also":["gestionnaires de paquets","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"L'outil le plus répandu pour garder l'historique des modifications du code, sous forme de commits et de branches."},{"id":"github","g":"build","word":"GitHub","text":"Un site web qui garde des dépôts Git en ligne, pour que les équipes partagent le code, relisent les modifications et suivent le travail."},{"id":"vcs","g":"build","word":"Gestion de versions","text":"Garder tout l'historique de chaque modification des fichiers, pour voir qui a changé quoi et revenir en arrière si besoin. Git fait ça.","also":["contrôle de version","gestion de version","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Cloner","text":"Faire ta propre copie complète d'un dépôt, avec son historique, sur ton ordinateur.","also":["clone","cloné","clonage","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (récupérer)","text":"Récupérer sur ton ordinateur les derniers commits de la copie partagée (comme GitHub). L'inverse de push.","also":["git pull","tirer","récupérer les changements"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branche principale","text":"La version officielle du code, celle dont tout le monde part, souvent appelée main ou master.","also":["main","master","branche master","master branch"]},{"id":"conflict","g":"build","word":"Conflit de fusion (merge conflict)","text":"Quand deux modifications touchent les mêmes lignes de façons différentes : l'ordinateur ne peut pas les réunir et une personne doit choisir.","also":["conflits de fusion","conflit de merge","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (différences)","text":"Un affichage qui montre exactement ce qui a changé entre deux versions : les lignes ajoutées et les lignes retirées.","also":["diffs","différences","comparaison"]},{"id":"fork","g":"build","word":"Fork (bifurcation)","text":"Ta propre copie du dépôt de quelqu'un d'autre, que tu peux modifier sans toucher à l'original.","also":["forks","forker","bifurcation","forked"]},{"id":"script","g":"build","word":"Script","text":"Un petit programme qui fait un travail tout seul, comme ranger des fichiers ou lancer l'appli.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (compilation du projet)","text":"Transformer le code en quelque chose de prêt à être exécuté, ou ce résultat prêt à l'emploi lui-même.","also":["builds","construire","génération"],"noTip":1},{"id":"compile","g":"build","word":"Compiler","text":"Traduire du code écrit par des personnes en une forme que l'ordinateur peut exécuter directement.","also":["compilation","compilateur","compile","compiler"]},{"id":"cli","g":"build","word":"Ligne de commande (CLI)","text":"Une fenêtre de texte où tu tapes des instructions pour l'ordinateur au lieu de cliquer. On dit aussi le terminal.","also":["ligne de commande","console","invite de commandes","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"Les réglages qui contrôlent le comportement d'un logiciel, gardés à part du code pour être faciles à changer.","also":["config","configuration","paramétrage","réglages"],"noTip":1},{"id":"envvar","g":"build","word":"Variable d'environnement","text":"Un réglage donné à un programme quand il démarre, souvent pour des adresses ou des mots de passe afin qu'ils ne soient pas écrits dans le code.","also":["variables d'environnement","env var","environment variable","environment variables"]},{"id":"debugging","g":"build","word":"Débogage","text":"Chercher pourquoi quelque chose ne marche pas, et le réparer.","also":["déboguer","debug","debugger","debugging","debugged"]},{"id":"pairing","g":"build","word":"Programmation en binôme","text":"Deux personnes (ou une personne et une IA) qui travaillent ensemble sur le même code, l'une tape et l'autre vérifie.","also":["pair programming","pairing","binôme","pair-programming"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Des explications écrites sur le fonctionnement de quelque chose ou sur la façon de s'en servir.","also":["documentation","docs","doc"],"noTip":1},{"id":"readme","g":"build","word":"README (fichier « lisez-moi »)","text":"Le premier fichier à lire dans un dépôt : ce qu'est le projet et comment le faire démarrer.","also":["READMEs","lisez-moi","readme"]},{"id":"legacy","g":"build","word":"Système hérité (legacy)","text":"Un ancien système encore utilisé et difficile à modifier, souvent parce que peu de gens le comprennent encore.","also":["systèmes hérités","code hérité","legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Dette technique","text":"Des raccourcis qui font gagner du temps maintenant mais ralentissent les changements plus tard, comme un prêt dont les intérêts s'accumulent. Le refactoring la rembourse.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Essayer un travail terminé pour vérifier qu'il fait ce qui était demandé, avant de l'accepter.","also":["tests","tester","testé","testée","testés","testées"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Abréviation de l’anglais quality assurance, l’assurance qualité : les vérifications automatiques qui tournent avant que quoi que ce soit passe en ligne. Quand la QA est rouge, quelque chose a échoué, et rien ne passe en ligne tant que ce n’est pas corrigé.","also":["contrôle qualité","contrôles qualité","assurance qualité"]},{"id":"testpile","g":"test","word":"Pile de tests","text":"Les cartes terminées qui attendent que tu les essaies, l’une après l’autre. Accepte-en une ou renvoie-la avec une note, et la suivante arrive.","also":["piles de tests"]},{"id":"autotest","g":"test","word":"Test automatisé","text":"Une vérification que l'ordinateur lance tout seul à chaque modification du code, pour repérer les erreurs tôt.","also":["tests automatisés","tests automatiques","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Test manuel","text":"Une personne qui essaie le travail à la main pour voir s'il se comporte comme il faut.","also":["tests manuels","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Test unitaire","text":"Une petite vérification automatique d'un tout petit morceau de code, pris seul.","also":["tests unitaires","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Test d'intégration","text":"Une vérification que plusieurs parties fonctionnent bien ensemble, et pas seulement une par une.","also":["tests d'intégration","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Test de bout en bout (E2E)","text":"Un test qui se comporte comme un vrai utilisateur du début à la fin, par exemple s'inscrire, acheter et payer.","also":["E2E","tests de bout en bout","end-to-end tests"]},{"id":"uat","g":"test","word":"Recette utilisateur (UAT)","text":"Les personnes qui ont demandé le travail l'essaient elles-mêmes et disent s'il fait ce dont elles ont besoin. Dans AI-gile, la pile des tests qui t'attendent en est l'équivalent.","also":["UAT","recette","tests d'acceptation","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"Régression","text":"Quelque chose qui marchait et qui ne marche plus après une modification. Les tests de régression vérifient que ce qui existait marche toujours.","also":["régressions","test de régression","tests de régression","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Test de fumée (smoke test)","text":"Une vérification très rapide que les choses principales marchent, par exemple juste après une mise en ligne. S'il échoue, on s'arrête et on regarde.","also":["tests de fumée","smoke test","smoke tests","test de vérification rapide"]},{"id":"exploratory","g":"test","word":"Test exploratoire","text":"Essayer le produit librement et le pousser dans tous les sens, pour trouver des problèmes que des vérifications prévues rateraient.","also":["tests exploratoires","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Cas de test","text":"Un scénario écrit à essayer : les étapes, et ce qui devrait se passer.","also":["cas de tests","scénario de test","test case","test cases"]},{"id":"coverage","g":"test","word":"Couverture de tests","text":"La part du code qui est vérifiée par des tests automatiques. Plus il y en a, plus c'est en général sûr, mais une couverture élevée seule ne prouve pas que ça marche bien.","also":["couverture de code","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Données de test","text":"Des informations d'exemple inventées, utilisées pendant les tests, pour qu'aucune donnée privée d'une vraie personne ne soit exposée.","also":["jeu de test","jeux de test","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Cas limite","text":"Une situation inhabituelle aux limites, comme un formulaire vide ou un nom avec une apostrophe, où les choses cassent souvent.","also":["cas limites","edge case","edge cases","cas extrême"]},{"id":"happypath","g":"test","word":"Scénario nominal (happy path)","text":"Le chemin normal où tout se passe bien. Un bon test essaie aussi les chemins où ça se passe mal."},{"id":"perftest","g":"test","word":"Test de performance","text":"Vérifier la rapidité de quelque chose et comment il tient quand il est très sollicité.","also":["tests de performance","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Test de charge","text":"Vérifier comment un système s'en sort quand beaucoup de gens l'utilisent en même temps.","also":["tests de charge","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Test de sécurité","text":"Chercher les faiblesses qui pourraient permettre à quelqu'un d'abuser d'un système ou de voir ce qu'il ne devrait pas.","also":["tests de sécurité","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Test d'accessibilité","text":"Vérifier que des personnes aux capacités différentes peuvent utiliser le produit, y compris avec un lecteur d'écran ou seulement un clavier.","also":["tests d'accessibilité","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting (analyse de style)","text":"Une vérification automatique qui repère les erreurs probables et le style brouillon dans le code, comme un correcteur d'orthographe pour les programmes.","also":["linter","lint","linting","analyse de style"]},{"id":"static","g":"test","word":"Analyse statique","text":"Chercher des problèmes dans le code en le lisant automatiquement, sans l'exécuter.","also":["analyse statique du code","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Test instable (flaky)","text":"Un test qui réussit parfois et échoue parfois sans raison claire, si bien qu'on ne peut pas lui faire entièrement confiance.","also":["tests instables","flaky test","flaky tests","test fragile"]},{"id":"repro","g":"test","word":"Reproduire (repro)","text":"Faire revenir un bug exprès en suivant les mêmes étapes, pour pouvoir l'étudier et le corriger. Écrire ces étapes est la partie la plus utile d'un rapport de bug.","also":["reproduction","reproductible","étapes pour reproduire","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Gravité","text":"L'ampleur des dégâts que cause un problème, de la petite gêne à l'arrêt complet.","also":["niveau de gravité","sévérité","severity","severity level"]},{"id":"deploy","g":"change","word":"Déploiement","text":"Mettre une nouvelle version en ligne, par exemple sur un serveur où les gens l'utilisent."},{"id":"release","g":"change","word":"Version","text":"Un lot nommé de travail terminé qui passe en ligne d’un coup, avec de courtes notes sur ce qui a changé. 🚀 Versions rédige les notes à partir des cartes terminées.","also":["versions","release","releases"]},{"id":"rollback","g":"change","word":"Retour arrière","text":"Revenir à la dernière version qui marchait quand une nouvelle pose problème. Dans AI-gile, cela crée une checklist à partir des étapes d’annulation notées sur chaque changement.","also":["rollback","revenir en arrière","retours arrière"]},{"id":"live","g":"change","word":"En ligne","text":"La vraie version que les gens utilisent, par opposition à une copie pour faire des essais. Les développeurs disent aussi la production, ou la prod.","also":["production","prod","live"],"noTip":1},{"id":"change","g":"change","word":"Changement","text":"Un changement prévu sur quelque chose dont les gens dépendent, écrit d’abord : quoi, pourquoi, le risque, quand, et comment l’annuler. Lance-en un avec 🔀 Demander un changement.","also":["changements","demande de changement","demandes de changement"],"noTip":1},{"id":"risk","g":"change","word":"Risque","text":"Quelque chose qui pourrait mal tourner, noté selon sa probabilité et sa gravité. ⚠️ Risques les garde dans une seule liste, le score le plus haut en premier, chacun avec une date pour y revenir.","also":["risques","registre des risques"]},{"id":"chgwin","g":"change","word":"Fenêtre de changement","text":"Les moments où les changements ont le droit de passer en ligne, comme un mardi soir tranquille. En dehors d’une fenêtre, une carte de changement ne peut pas être terminée, sauf urgence.","also":["fenêtres de changement"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Un vote rapide juste avant qu’un changement passe en ligne : chaque personne qui doit valider dit Go ou No go. Ça n’avance que si tout le monde est d’accord.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Validation","text":"Attendre un oui avant que le travail commence. Une carte créée par un ami, ou un changement, attend dans ✅ Validations jusqu’à ce que tu l’acceptes ou la refuses.","also":["validations","approbation","approbations"]},{"id":"quiettime","g":"change","word":"Plage de calme","text":"Un moment, comme un stream, une démo ou la nuit, pendant lequel rien ne passe en ligne. Les équipes continuent de travailler et de tester, mais la mise en ligne attend la fin. Ailleurs, on parle de gel des changements.","also":["plages de calme","gel des changements","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Une façon de travailler où ceux qui construisent le logiciel et ceux qui le font tourner forment une seule équipe, avec beaucoup d'automatisation, pour que les changements soient mis en ligne souvent et sans risque."},{"id":"cicd","g":"change","word":"CI/CD (intégration et livraison continues)","text":"Les changements de chacun sont réunis souvent dans la version principale et vérifiés automatiquement à chaque fois (intégration continue), si bien que le logiciel est toujours prêt à être mis en ligne d'un clic (livraison continue).","also":["CI/CD","CI","CD","intégration continue","livraison continue","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Déploiement continu","text":"Un cran de plus que la livraison continue : chaque changement qui passe les vérifications est mis en ligne tout seul, sans bouton à presser.","also":["déploiements continus","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (chaîne automatisée)","text":"La série automatique d'étapes que traverse un changement avant d'être en ligne, comme construire, tester, puis déployer.","also":["pipelines","chaîne d'intégration","chaîne automatisée"]},{"id":"environment","g":"change","word":"Environnement","text":"Une copie séparée du système pour un usage précis, par exemple une pour construire, une pour tester et celle qui est en ligne.","also":["environnements","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Environnement de développement","text":"La copie dans laquelle travaille un développeur, souvent sur son propre ordinateur, où casser des choses ne fait de mal à personne.","also":["env de dev","dev environment","development environment"]},{"id":"testenv","g":"change","word":"Environnement de test","text":"Une copie séparée du système utilisée uniquement pour tester, afin de ne pas toucher au vrai service.","also":["environnements de test","test environment","test environments"]},{"id":"staging","g":"change","word":"Préproduction (staging)","text":"Une dernière copie montée exactement comme la version en ligne, pour une vérification finale avant qu'un changement n'y passe.","also":["pré-production","préprod","staging","staging environment","environnement de préproduction"]},{"id":"artifact","g":"change","word":"Artefact de build","text":"Le fichier ou le lot que produit un build, prêt à être rangé, vérifié ou mis en ligne.","also":["artefacts de build","build artifact","build artifacts","artefact"]},{"id":"hotfix","g":"change","word":"Correctif urgent (hotfix)","text":"Une réparation urgente mise en ligne vite, en dehors du plan normal, parce que quelque chose d'important est cassé.","also":["hotfix","hotfixes","correctif d'urgence"]},{"id":"patch","g":"change","word":"Correctif (patch)","text":"Une petite mise à jour qui corrige un bug ou ferme une faille de sécurité. Appliquer vite les correctifs de sécurité est important.","also":["correctifs","patch","patches","correctif de sécurité","security patch","security patches"]},{"id":"version","g":"change","word":"Numéro de version","text":"Une étiquette comme 2.4.1 qui dit quelle version tu as. Souvent, le premier nombre change pour les grands changements et le dernier pour les petites corrections.","also":["numéros de version","versionnage sémantique","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Notes de version","text":"Une courte liste en langage clair de ce qui a changé dans une version, pour ceux qui l'utilisent, avec les corrections et les limites connues. On dit aussi changelog.","also":["journal des modifications","changelog","release notes","change log"]},{"id":"flag","g":"change","word":"Feature flag (interrupteur de fonctionnalité)","text":"Un interrupteur pour activer ou couper une fonctionnalité, si bien qu'un nouveau travail peut être mis en ligne caché, puis activé (ou désactivé) sans nouvelle version.","also":["feature flags","feature toggle","feature toggles","interrupteur de fonctionnalité","bascule de fonctionnalité"]},{"id":"rollfwd","g":"change","word":"Corriger en avant (roll forward)","text":"Réparer une mauvaise version en sortant vite une nouvelle version corrigée plutôt qu'en revenant à l'ancienne.","also":["roll forward","correction en avant","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Déploiement canari","text":"Mettre un changement en ligne d'abord pour un petit groupe, puis pour tout le monde seulement si tout se passe bien. Le nom vient des canaris que les mineurs emportaient sous terre pour être alertés à temps.","also":["mise en ligne canari","canary release","canary releases","canary","release canary"]},{"id":"bluegreen","g":"change","word":"Déploiement blue-green","text":"Garder deux copies du système en ligne et faire passer les gens d'un seul coup sur la nouvelle, pour pouvoir revenir tout de suite en arrière si ça tourne mal.","also":["blue-green","blue green deployment","déploiement bleu-vert","bleu-vert"]},{"id":"zerodown","g":"change","word":"Déploiement sans interruption","text":"Mettre une nouvelle version en ligne sans que le service ne s'arrête jamais pour ses utilisateurs.","also":["zéro interruption","sans coupure","zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Gestion des changements","text":"Aider les changements à réussir : peser le risque, obtenir la bonne validation et choisir un bon moment. On dit aussi change management.","also":["change management","change enablement","conduite du changement"]},{"id":"cab","g":"change","word":"Comité des changements (CAB)","text":"Un groupe qui examine les changements importants et décide s'ils peuvent avoir lieu, et quand.","also":["CAB","comité consultatif des changements","change advisory board"]},{"id":"stdchange","g":"change","word":"Changement standard","text":"Un changement à faible risque, fait de la même façon éprouvée à chaque fois, donc approuvé d'avance.","also":["changements standard","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Changement normal","text":"Un changement qu'il faut examiner et approuver avant de le réaliser.","also":["changements normaux","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Changement d'urgence","text":"Un changement qui doit avoir lieu tout de suite pour réparer ou éviter un gros problème, avec une validation plus rapide en conséquence.","also":["changements d'urgence","changement urgent","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automatisation","text":"Faire faire à l'ordinateur un travail répété tout seul, pour que ce soit plus rapide et fait de la même façon à chaque fois.","also":["automatiser","automatisé","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"Les machines, les réseaux et les services sur lesquels tourne un logiciel.","also":["infra","infrastructures"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Décrire tes serveurs et leurs réglages dans des fichiers gardés avec le code, pour pouvoir les reconstruire exactement de la même façon à chaque fois.","also":["IaC","infrastructure en tant que code","infrastructure programmable"]},{"id":"cloud","g":"change","word":"Cloud (informatique en nuage)","text":"Louer des ordinateurs, du stockage et des services à un gros fournisseur par internet, au lieu de posséder les machines toi-même.","also":["le cloud","nuage","informatique en nuage","the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Fournisseur cloud","text":"Une entreprise qui loue de la puissance informatique par internet, comme Amazon Web Services (AWS), Microsoft Azure ou Google Cloud.","also":["fournisseurs cloud","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hébergement","text":"L'endroit où ton appli ou ton site vit et tourne pour que les gens puissent y accéder, en général loué à une entreprise.","also":["hébergé","hébergeur","hosting"]},{"id":"domain","g":"change","word":"Nom de domaine","text":"L'adresse web que les gens tapent, comme example.com. Tu la loues à l'année, donc il faut la renouveler.","also":["noms de domaine","domaine","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Abréviation de « système de noms de domaine » : l'annuaire d'internet, qui transforme un nom comme example.com en adresse du bon ordinateur.","also":["système de noms de domaine","domain name system"]},{"id":"container","g":"change","word":"Conteneur","text":"Un paquet scellé qui contient une appli et tout ce dont elle a besoin, pour qu'elle tourne de la même façon sur n'importe quel ordinateur. Docker est l'outil le plus connu.","also":["conteneurs","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Machine virtuelle (VM)","text":"Un faux ordinateur qui tourne à l'intérieur d'un vrai, pour qu'une grosse machine puisse en faire office de plusieurs.","also":["VM","VMs","machines virtuelles","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (sans serveur)","text":"Faire tourner du code sans s'occuper soi-même d'aucun serveur : le fournisseur le lance quand il le faut et tu paies ce que tu utilises."},{"id":"lb","g":"change","word":"Répartiteur de charge","text":"Ce qui répartit les visiteurs entre plusieurs serveurs, pour qu'aucun ne soit submergé.","also":["répartiteurs de charge","équilibreur de charge","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache (mémoire tampon)","text":"Une réserve pratique de résultats récents gardés à portée de main, pour ne pas avoir à les récupérer ou à les recalculer. La vider peut réparer des pages qui paraissent périmées.","also":["caches","mise en cache","antémémoire","caching","cached"]},{"id":"cdn","g":"change","word":"Réseau de diffusion de contenu (CDN)","text":"Un ensemble de serveurs dans le monde entier qui gardent des copies de tes pages et de tes images près de tes visiteurs, pour qu'elles se chargent vite.","also":["CDN","réseau de diffusion","content delivery network"]},{"id":"migration","g":"change","word":"Migration","text":"Déplacer des données ou des systèmes d'un ancien montage vers un nouveau, ou modifier avec soin l'organisation d'une base de données.","also":["migrations","migration de base de données","database migration"]},{"id":"service","g":"run","word":"Service","text":"Quelque chose que tu as construit et dont les gens dépendent, comme un site ou une appli, entretenu pour que ça continue de marcher. Coche « Ce projet est un service » et indique ce qu’il offre, qui l’utilise et qui est d’astreinte.","also":["services"]},{"id":"uptimepct","g":"run","word":"Disponibilité (uptime)","text":"La part du temps où un service fonctionne, en général en pourcentage. 99,9 % laisse quand même environ 43 minutes d'arrêt par mois.","also":["uptime","taux de disponibilité","pourcentage de disponibilité","uptime percentage"]},{"id":"uptime","g":"run","word":"Contrôle de disponibilité","text":"Une vérification automatique, toutes les quelques minutes, que ton service répond toujours. Si elle échoue plusieurs fois de suite, AI-gile ouvre tout seul une carte d’incident.","also":["disponibilité","uptime","contrôles de disponibilité"]},{"id":"statuspage","g":"run","word":"Page d’état","text":"Une page publique qui montre si un service fonctionne (vert, orange ou rouge) avec la dernière nouvelle, pour que les gens qui l’utilisent puissent regarder au lieu de demander.","also":["pages d’état","page de statut","status page"]},{"id":"desk","g":"run","word":"Guichet de service","text":"L'endroit où arrivent les questions et les signalements des gens qui utilisent ton service. AI-gile range chacun en demande, incident ou idée, et le signale quand il ressemble à quelque chose de déjà signalé.","also":["guichets de service","guichet","service desk","support"]},{"id":"svcrequest","g":"run","word":"Demande de service","text":"Quelqu'un qui demande quelque chose d'ordinaire, comme un nouveau compte ou un coup de main, au lieu de signaler une panne. Elle attend son tour; un incident passe avant.","also":["demandes de service"]},{"id":"incident","g":"run","word":"Incident","text":"Quelque chose qui est cassé en ce moment même pour les gens qui l’utilisent, comme un site en panne. Une carte 🔥 incident passe devant tout le monde : le remettre en marche passe en premier.","also":["incidents"]},{"id":"major","g":"run","word":"Incident majeur","text":"Un gros incident : beaucoup de gens touchés, ou de l’argent ou des données en danger. Un bouton met toutes les équipes dessus (essaim), réveille la personne d’astreinte et demande un point d’état toutes les 30 minutes.","also":["incidents majeurs"]},{"id":"oncall","g":"run","word":"Astreinte","text":"Être celui ou celle qui répond quand quelque chose casse, même la nuit. Chaque service a un membre de l’équipe d’astreinte, réveillé en premier pour ses incidents.","also":["d’astreinte","astreintes","on-call"]},{"id":"replyby","g":"run","word":"Délai de réponse","text":"Combien de temps une carte peut attendre une première réponse, par exemple une heure pour un incident. Ensuite, elle reçoit une horloge rouge, pour que rien ne soit oublié en silence. On parle aussi d’objectif de réponse.","also":["délais de réponse","objectif de réponse","objectifs de réponse"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un court retour en arrière après un incident : ce qui s’est passé, ce qui a aidé et ce qu’il faut changer, sans accuser personne. Un incident ne peut pas être clos sans lui.","also":["post-mortems","postmortem","retour d’expérience"]},{"id":"problem","g":"run","word":"Problème","text":"La cause cachée derrière un ou plusieurs incidents. Une carte 🧩 problème regroupe les incidents qui reviennent sans cesse, pour que la cause soit trouvée et corrigée pour de bon.","also":["problèmes"],"noTip":1},{"id":"rootcause","g":"run","word":"Cause racine","text":"La vraie raison pour laquelle quelque chose a cassé, pas seulement ce que tu as vu mal tourner. Corrige la cause racine et l’incident arrête de revenir.","also":["causes racines","cause profonde"]},{"id":"workaround","g":"run","word":"Contournement","text":"Un moyen de faire tourner les choses en attendant la vraie correction, comme redémarrer quelque chose quand ça bloque. Il est noté sur la carte du problème pour que personne n’ait à le retrouver.","also":["contournements","solution de contournement","workaround"]},{"id":"knownerror","g":"run","word":"Erreur connue","text":"Un problème dont la cause est comprise et qui a un contournement, mais qui n’est pas encore corrigé. 🧩 Erreurs connues les liste, pour que tout le monde utilise le contournement au lieu de chercher à nouveau.","also":["erreurs connues"]},{"id":"runbook","g":"run","word":"Runbook","text":"Des instructions pas à pas pour régler un type de souci connu, pour que ce soit fait de la même façon, vite, à chaque fois. Après un gros incident, l’équipe peut en proposer un que tu valides.","also":["runbooks","procédure d’exploitation"]},{"id":"ci","g":"run","word":"Élément de configuration","text":"Une chose dont ton service dépend, comme un serveur, un domaine, un certificat, une clé ou un fournisseur. 🗂️ Éléments de configuration les liste par service, pour que tu voies ce qu'un incident touche et ce qu'il faut renouveler ou sauvegarder.","also":["éléments de configuration","élément de configuration","CI"]},{"id":"expiry","g":"run","word":"Date d'expiration","text":"AI-gile garde un œil sur des dates comme l'expiration d'un certificat ou d'un domaine. Dans les 30 jours avant la date, il crée une carte pour le renouveler, pour que rien ne s'arrête par surprise.","also":["dates d'expiration","expiration","suivi des expirations"]},{"id":"backup","g":"run","word":"Sauvegarde","text":"Une copie enregistrée de tes données d’avant, sur laquelle te rabattre si quelque chose est perdu ou abîmé. AI-gile fait chaque jour une sauvegarde de tes tableaux.","also":["sauvegardes","backup","backups"]},{"id":"restore","g":"run","word":"Restaurer","text":"Remettre des données à partir d’une sauvegarde. Une sauvegarde ne compte vraiment que si tu sais qu’elle peut être restaurée, alors ça vaut le coup d’essayer de temps en temps.","also":["restauration","restauré","restaurée"]},{"id":"svcreview","g":"run","word":"Bilan de service","text":"Un regard en arrière sur un mois d'un service : incidents ouverts et réglés, rapidité des réponses, disponibilité et tokens utilisés. Le Bilan mensuel le montre pour chaque service.","also":["bilans de service","bilan mensuel","bilans mensuels"]},{"id":"accessreview","g":"run","word":"Revue des accès","text":"Vérifier tous les 90 jours qui peut encore entrer : liens de partage, rôles des amis et secrets gardés. Tu gardes ou supprimes chacun, pour que les vieux accès ne traînent pas.","also":["revues des accès","revue d'accès"]},{"id":"improvements","g":"run","word":"Liste d'améliorations","text":"Tout ce que l'équipe a décidé d'améliorer, au même endroit : suggestions de rétro, actions de revue et corrections de problèmes, chacune avec son statut. Tu la trouves sous 📈 Améliorations.","also":["listes d'améliorations","améliorations"]},{"id":"tokencap","g":"run","word":"Plafond de tokens","text":"Une limite mensuelle des tokens que les agents d'un service peuvent utiliser. À 80 %, tu reçois un avertissement; à 100 %, leur travail en arrière-plan attend le mois suivant ou que tu relèves le plafond.","also":["plafonds de tokens","plafond mensuel de tokens"]},{"id":"svcmgmt","g":"run","word":"Gestion des services","text":"Tout ce qu'il faut pour qu'un service reste utile et fonctionne pour ceux qui comptent dessus, jour après jour.","also":["gérer un service","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Un guide très utilisé de bonnes pratiques de gestion des services, qui couvre des sujets comme les incidents, les problèmes et les changements. Le nom signifiait à l'origine IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestion des services informatiques (ITSM)","text":"Gérer la technologie comme un service rendu aux gens, avec des façons claires de traiter les demandes, les incidents, les changements et les améliorations.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Service managé (infogéré)","text":"Un service que quelqu'un d'autre fait tourner et entretient pour toi, selon un accord sur la qualité attendue.","also":["services managés","service géré","infogérance","managed service","managed services"]},{"id":"svcowner","g":"run","word":"Responsable de service","text":"La personne qui répond d'un service dans son ensemble : son bon fonctionnement, son coût et ses améliorations.","also":["responsables de service","propriétaire du service","service owner","service owners"]},{"id":"sla","g":"run","word":"Accord de niveau de service (SLA)","text":"Une promesse écrite faite aux clients sur la qualité d'un service, comme « disponible 99,9 % du temps » ou « réponse sous une heure », souvent avec remboursement si elle n'est pas tenue.","also":["SLA","SLAs","accords de niveau de service","service level agreement"]},{"id":"slo","g":"run","word":"Objectif de niveau de service (SLO)","text":"L'objectif que l'équipe se fixe elle-même sur la qualité d'un service sur une période, en général un peu plus strict que le SLA par sécurité.","also":["SLO","SLOs","objectif de service"]},{"id":"sli","g":"run","word":"Indicateur de niveau de service (SLI)","text":"La mesure réelle que tu compares à un objectif, comme la part des visites qui se sont chargées sans problème.","also":["SLI","SLIs","indicateur de service"]},{"id":"availability","g":"run","word":"Disponibilité","text":"Le fait que les gens puissent utiliser un service quand ils en ont besoin, souvent mesuré par le taux de disponibilité (uptime).","also":["haute disponibilité","availability","high availability"]},{"id":"downtime","g":"run","word":"Temps d'arrêt (downtime)","text":"Le temps où un service ne fonctionne pas ou est éteint, prévu ou non.","also":["indisponibilité","arrêt de service","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Budget d'erreur","text":"La petite marge de pannes que permet ton objectif de fiabilité. Tant qu'il en reste, tu peux prendre des risques avec les changements; une fois épuisée, tu ralentis.","also":["budgets d'erreur","error budget","error budgets"]},{"id":"outage","g":"run","word":"Panne","text":"Un moment où un service est à l'arrêt ou gravement cassé pour ses utilisateurs.","also":["pannes","interruption de service","outage","outages"]},{"id":"degraded","g":"run","word":"Service dégradé","text":"Ça marche, mais mal : c'est lent, ou certaines parties ne fonctionnent pas.","also":["dégradé","fonctionnement dégradé","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Supervision (monitoring)","text":"Surveiller un service automatiquement et en permanence, pour repérer les problèmes, idéalement avant que les utilisateurs ne s'en aperçoivent.","also":["monitoring","surveillance","supervisé"]},{"id":"observability","g":"run","word":"Observabilité","text":"La capacité de savoir ce qui se passe à l'intérieur d'un système en le regardant de l'extérieur, grâce à ses journaux, ses chiffres et ses traces.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Journal (log)","text":"Un journal de bord où un programme note au fur et à mesure ce qu'il fait, pour comprendre ensuite ce qui s'est mal passé.","also":["journaux","logs","journalisation","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Le relevé du chemin que suit une demande à travers les différentes parties d'un système, étape par étape, qui montre où elle a ralenti.","also":["traces","traçage","tracing"]},{"id":"latency","g":"run","word":"Latence","text":"Le temps que met quelque chose à répondre, comme l'attente entre le clic et l'apparition de la page.","also":["temps de réponse","délai de réponse"]},{"id":"alert","g":"run","word":"Alerte","text":"Un message automatique qui prévient que quelque chose demande de l'attention, par exemple le site web qui ne répond plus.","also":["alertes","alerting","alert","alerts"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Fatigue d'alerte","text":"Quand il y a tellement d'alertes que les gens se mettent à les ignorer, même les importantes.","also":["lassitude d'alerte","alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Tableau de bord","text":"Un écran qui montre d'un coup d'œil les chiffres et les états les plus importants.","also":["tableaux de bord","dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Appel d'astreinte (paging)","text":"Appeler ou réveiller en urgence la personne d'astreinte pour un problème.","also":["paging","alerter l'astreinte","appel d'urgence","paged"]},{"id":"escalation","g":"run","word":"Escalade","text":"Faire appel à quelqu'un de plus compétent ou ayant plus d'autorité quand un problème ne peut pas être réglé au niveau actuel, ou pas assez vite.","also":["escalader","escaladé","escalate","escalated"]},{"id":"triage","g":"run","word":"Tri (triage)","text":"Trier rapidement les problèmes qui arrivent selon leur urgence et leur importance, pour que le pire soit traité en premier.","also":["triage","trier","trié","triaged"]},{"id":"impact","g":"run","word":"Impact","text":"À quel point quelque chose touche les gens : combien, et avec quelle gravité.","noTip":1},{"id":"urgency","g":"run","word":"Urgence","text":"La rapidité avec laquelle quelque chose doit être traité. L'impact et l'urgence ensemble fixent la priorité.","noTip":1},{"id":"plevels","g":"run","word":"Niveaux de priorité (P1, P2…)","text":"Des étiquettes qui disent l'urgence d'un problème. P1 est le plus grave et demande d'agir tout de suite.","also":["P1","P2","P3","P4","niveaux de priorité"]},{"id":"queue","g":"run","word":"File de tickets","text":"La liste des demandes et des incidents qui attendent d'être pris en charge.","also":["files de tickets","file d'attente","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Premier niveau et deuxième niveau","text":"Des niveaux de support : le premier niveau prend l'appel et règle les choses simples; le deuxième a des compétences plus poussées pour les cas difficiles. On dit aussi niveau 1 et niveau 2.","also":["premier niveau","deuxième niveau","support de niveau 1","niveau 1","niveau 2","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Responsable d'incident","text":"La personne qui dirige la réponse à un incident, pour que tout le monde sache qui décide et qui fait quoi.","also":["commandant d'incident","responsables d'incident","incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Temps de réponse","text":"Le temps qu'il faut avant que quelqu'un prenne en charge pour la première fois une demande ou un incident.","also":["délai de prise en charge","response time","response times"]},{"id":"resolution","g":"run","word":"Temps de résolution","text":"Le temps qu'il faut pour régler complètement une demande ou un incident, du signalement à la réparation.","also":["délai de résolution","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Temps moyen de rétablissement (MTTR)","text":"En moyenne, le temps qu'il faut pour remettre un service en marche après une panne. Le MTTR peut vouloir dire des choses légèrement différentes, alors précise ce que tu mesures.","also":["MTTR","temps moyen de réparation","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Temps moyen entre pannes (MTBF)","text":"En moyenne, le temps pendant lequel un service tourne avant que quelque chose ne casse.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Base de gestion des configurations (CMDB)","text":"La liste de tous tes éléments de configuration et de la façon dont ils sont reliés, pour voir ce qui dépend de quoi.","also":["CMDB","base de données de configuration"]},{"id":"asset","g":"run","word":"Actif (asset)","text":"Tout ce qui a de la valeur et que tu possèdes ou paies pour faire tourner le service, comme un ordinateur portable, une licence de logiciel ou un nom de domaine.","also":["actifs","équipement","bien","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Planification de capacité","text":"S'assurer qu'il y aura assez de puissance informatique, de stockage et de personnes pour ce qui arrive.","also":["plan de capacité","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Mise à l'échelle (scaling)","text":"Faire face à plus d'utilisateurs en donnant plus de puissance à une machine (scaling up) ou en ajoutant des machines (scaling out).","also":["scaling","passage à l'échelle","montée en charge","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Continuité d'activité","text":"Des plans pour que l'essentiel continue quand quelque chose de grave tourne mal, comme la perte d'un bureau, d'un fournisseur clé ou des ordinateurs.","also":["plan de continuité d'activité","PCA","business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Reprise après sinistre (DR)","text":"Le plan et les outils pour remettre un service en marche après un événement grave, comme la perte d'un centre de données entier.","also":["DR","plan de reprise d'activité","PRA","disaster recovery"]},{"id":"rto","g":"run","word":"Durée maximale d'interruption admissible (RTO)","text":"La durée maximale pendant laquelle un service peut rester à l'arrêt après un sinistre avant de devoir être rétabli.","also":["RTO","objectif de temps de reprise","recovery time objective"]},{"id":"rpo","g":"run","word":"Perte de données maximale admissible (RPO)","text":"La quantité de données récentes que tu peux te permettre de perdre, mesurée en temps. Un RPO d'une heure veut dire des sauvegardes au moins toutes les heures.","also":["RPO","objectif de point de reprise","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redondance","text":"Avoir des éléments de rechange prêts, comme un deuxième serveur, pour qu'une panne n'arrête pas le service.","also":["redondant","redundancy"]},{"id":"failover","g":"run","word":"Bascule automatique (failover)","text":"Passer tout seul sur un système de secours quand le système habituel tombe en panne.","also":["failover","basculement","fail over","basculer"]},{"id":"spof","g":"run","word":"Point de défaillance unique","text":"Un élément qui entraîne tout avec lui quand il casse, parce qu'il n'y a pas de rechange.","also":["points de défaillance uniques","SPOF","point unique de défaillance","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Fenêtre de maintenance","text":"Un moment prévu où un service peut être mis en pause ou ralenti pour l'entretien, annoncé d'avance aux utilisateurs.","also":["fenêtres de maintenance","maintenance planifiée","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Passation","text":"Transmettre du travail, des connaissances et des responsabilités à une autre personne ou équipe, pour que rien ne se perde.","also":["passations","transfert de responsabilité","handover","handovers"]},{"id":"kb","g":"run","word":"Base de connaissances","text":"Un ensemble d'articles d'aide et de réponses, pour les utilisateurs et pour l'équipe.","also":["bases de connaissances","base documentaire","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Satisfaction client (CSAT)","text":"Une note donnée par les utilisateurs pour dire leur degré de satisfaction, souvent demandée une fois la demande clôturée.","also":["CSAT","satisfaction des utilisateurs","customer satisfaction"]},{"id":"supplier","g":"run","word":"Fournisseur","text":"Une entreprise extérieure sur laquelle tu comptes, comme ton hébergeur. On dit aussi prestataire ou tiers.","also":["fournisseurs","prestataire","tiers","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Fin de service","text":"Éteindre un service pour de bon, en sécurité : prévenir ses utilisateurs, s'occuper de ses données et de ses accès, et mettre fin à ses coûts.","also":["arrêt d'un service","retrait d'un service","désactivation","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Fin de vie (EOL)","text":"Quand un produit ne reçoit plus de mises à jour ni de support de son fabricant, et qu'il faut donc le remplacer.","also":["EOL","fin de support","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersécurité","text":"Protéger les systèmes et les données contre les intrusions, le vol et les dégâts.","also":["sécurité informatique","cyber sécurité","cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Authentification","text":"Vérifier qui est quelqu'un, en général avec un mot de passe ou un code. Souvent abrégé en authn.","also":["authn","s'authentifier","authentication"]},{"id":"authz","g":"sec","word":"Autorisation","text":"Vérifier ce que quelqu'un a le droit de faire une fois qu'on sait qui il est. Souvent abrégé en authz.","also":["authz","habilitation","droits d'accès","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Authentification multifacteur (MFA)","text":"Se connecter avec deux preuves ou plus, comme un mot de passe plus un code sur ton téléphone. On dit aussi double authentification (2FA).","also":["MFA","2FA","double authentification","vérification en deux étapes","authentification à deux facteurs","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Authentification unique (SSO)","text":"Se connecter une seule fois pour accéder à beaucoup de systèmes, comme utiliser partout ton compte professionnel.","also":["SSO","connexion unique","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Gestionnaire de mots de passe","text":"Une appli qui crée des mots de passe solides et les retient pour toi.","also":["gestionnaires de mots de passe","coffre-fort de mots de passe","password manager","password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"Un mot de passe, une clé ou un autre code privé qu'un programme utilise pour accéder à quelque chose. Il ne doit jamais être partagé ni écrit dans le code.","also":["secrets","identifiants secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Clé d'API","text":"Un code secret qui permet à un programme d'utiliser l'API d'un autre service, et qui montre qui l'utilise (et qui paie).","also":["clés d'API","clé API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Jeton d'accès","text":"Un laissez-passer temporaire qui prouve qu'un programme a le droit d'entrer, pour ne pas redemander ton mot de passe à chaque fois. À ne pas confondre avec un token d'IA.","also":["jetons d'accès","token d'accès","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Chiffrement","text":"Brouiller des informations pour que seule une personne avec la bonne clé puisse les lire.","also":["cryptage","chiffré","chiffrer","crypté","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"La façon sécurisée dont voyagent les pages web, signalée par le cadenas dans ton navigateur, pour que personne entre les deux ne puisse les lire ni les modifier."},{"id":"cert","g":"sec","word":"Certificat SSL/TLS","text":"Une carte d'identité numérique qui permet à un site web de prouver qui il est et d'utiliser HTTPS. Elle expire, donc il faut la renouveler.","also":["certificat TLS","certificat SSL","certificat","certificats","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Autorisations (permissions)","text":"Les règles qui disent qui peut voir ou modifier quoi.","also":["permissions","permission","droits","droits d'accès"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Moindre privilège","text":"Ne donner à chaque personne ou programme que l'accès dont il a vraiment besoin, et seulement le temps qu'il en a besoin.","also":["principe du moindre privilège","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Contrôle d'accès par rôles (RBAC)","text":"Donner l'accès selon un rôle, comme lecteur ou éditeur, plutôt que personne par personne.","also":["RBAC","accès par rôle","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnérabilité","text":"Une faiblesse que quelqu'un pourrait utiliser pour s'introduire ou faire du mal.","also":["vulnérabilités","faille","faille de sécurité","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Faille zero-day","text":"Une faille que les attaquants connaissent avant que les créateurs du logiciel aient eu le temps de la corriger.","also":["zero-day","zero-days","zero day","faille du jour zéro","faille inconnue"]},{"id":"malware","g":"sec","word":"Logiciel malveillant (malware)","text":"Un logiciel nuisible, comme les virus, fait pour abîmer, espionner ou voler.","also":["malware","logiciels malveillants"]},{"id":"ransomware","g":"sec","word":"Rançongiciel (ransomware)","text":"Un logiciel malveillant qui verrouille tes fichiers et réclame de l'argent pour les débloquer. De bonnes sauvegardes sont la meilleure défense.","also":["ransomware","rançongiciels","attaque par rançongiciel","ransomware attack"]},{"id":"phishing","g":"sec","word":"Hameçonnage (phishing)","text":"De faux messages qui essaient de te piéger pour que tu donnes des mots de passe ou de l'argent, ou que tu ouvres quelque chose de nuisible.","also":["phishing","filoutage","e-mail d'hameçonnage","courriel d'hameçonnage","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Ingénierie sociale","text":"Piéger des personnes, plutôt que des ordinateurs, pour obtenir un accès, comme un faux appel du « support informatique »."},{"id":"firewall","g":"sec","word":"Pare-feu","text":"Un gardien qui décide quel trafic réseau peut entrer ou sortir.","also":["pare-feux","firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Abréviation de « réseau privé virtuel » : une liaison privée et brouillée à travers internet, souvent utilisée pour accéder en sécurité aux systèmes du travail.","also":["réseau privé virtuel","virtual private network"]},{"id":"ddos","g":"sec","word":"Déni de service (DoS, DDoS)","text":"Inonder un service de tellement de faux trafic que les vraies personnes ne peuvent plus l'utiliser. DDoS veut dire que ça vient de beaucoup d'ordinateurs à la fois.","also":["DoS","DDoS","déni de service","attaque DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Test d'intrusion (pentest)","text":"Engager des experts bienveillants pour essayer de s'introduire, afin de trouver les faiblesses avant que de vrais attaquants ne les trouvent.","also":["pentest","pen test","tests d'intrusion","test de pénétration","pen testing","penetration testing","penetration test"]},{"id":"audit","g":"sec","word":"Audit de sécurité","text":"Une vérification minutieuse de la protection de quelque chose, par rapport à une liste de bonnes pratiques.","also":["audits de sécurité","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modélisation des menaces","text":"Réfléchir à qui pourrait attaquer quelque chose, comment, et ce que tu ferais pour l'en empêcher.","also":["modèle de menaces","analyse des menaces","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Fuite de données","text":"Quand des informations privées arrivent à des gens qui ne devraient pas les avoir, ou sont perdues ou modifiées sans autorisation.","also":["violation de données","fuites de données","data breach","data breaches","brèche"]},{"id":"pii","g":"sec","word":"Données personnelles","text":"Toute information sur une personne qui peut être identifiée, comme un nom, une adresse courriel ou un lieu. On dit aussi PII en anglais.","also":["donnée personnelle","PII","informations personnelles","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"RGPD","text":"La loi européenne sur les données personnelles (le Royaume-Uni a sa propre version) : ne collecte que ce dont tu as besoin, protège-le bien, et laisse chacun consulter ou supprimer ses données.","also":["GDPR","règlement général sur la protection des données","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Protection des données","text":"S'occuper correctement des données personnelles, dans le respect de la loi.","also":["loi sur la protection des données","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Politique de confidentialité","text":"Une page publique qui dit quelles données personnelles tu collectes, pourquoi, et ce que tu en fais.","also":["déclaration de confidentialité","avis de confidentialité","privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consentement","text":"Le oui clair et libre d'une personne à ce que ses données soient utilisées d'une certaine façon. Elle peut le retirer à tout moment.","also":["opt-in","accord","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie (témoin de connexion)","text":"Un petit fichier qu'un site web enregistre dans ton navigateur pour se souvenir de choses, comme ta connexion à ton compte. Certains demandent d'abord ton consentement.","also":["cookies","témoin de connexion","témoins"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimisation des données","text":"Ne collecter et ne garder que les données personnelles dont tu as vraiment besoin pour le travail.","also":["limitation des données","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Durée de conservation des données","text":"Combien de temps les données sont gardées avant d'être supprimées. Ne pas les garder plus longtemps que nécessaire est plus sûr et souvent exigé par la loi.","also":["conservation des données","rétention","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Transformer des données pour que plus personne ne puisse raisonnablement être identifié à partir d'elles.","also":["anonymisé","données anonymes","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Remplacer les noms et d'autres détails par des codes, avec une clé gardée à part pour les relier. Ce sont toujours des données personnelles.","also":["pseudonymisé","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Accord de traitement des données (DPA)","text":"Un contrat qui dit comment un fournisseur peut traiter des données personnelles en ton nom.","also":["DPA","contrat de sous-traitance","data processing agreement"]},{"id":"dpia","g":"sec","word":"Analyse d'impact sur la protection des données (AIPD)","text":"Un examen attentif, avant de commencer, de la façon dont un projet d'utilisation de données personnelles pourrait toucher les gens et de comment réduire les risques.","also":["AIPD","DPIA","analyse d'impact","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Journal d'audit","text":"Un relevé de qui a fait quoi et quand, pour pouvoir vérifier les actions plus tard.","also":["journaux d'audit","piste d'audit","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Conformité","text":"Respecter les lois, règles et normes qui s'appliquent à toi, et pouvoir montrer que tu le fais.","also":["conforme","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Une norme internationale bien connue pour gérer la sécurité de l'information. Les entreprises peuvent obtenir une certification ISO 27001.","also":["ISO/IEC 27001","norme ISO 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un rapport américain, vérifié par des auditeurs extérieurs, qui montre qu'une entreprise s'occupe correctement des données de ses clients.","also":["SOC2","rapport SOC 2"]},{"id":"agent","g":"ai","word":"Agent","text":"Une IA qui travaille seule sur une tâche : elle lit le code, fait des changements, lance des vérifications et fait son rapport.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"L'unité dans laquelle on compte la consommation de l'IA : en gros, quelques lettres de texte lues ou écrites. Moins tu en utilises, plus il te reste de forfait.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Une petite commande qui s'exécute toute seule à un moment précis, par ex. au démarrage d'une session IA, pour que l'équipe entende tes commentaires.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intelligence artificielle (IA)","text":"Des systèmes informatiques qui font des choses qu'on croit d'habitude réservées aux humains, comme écrire, répondre à des questions ou reconnaître des images.","also":["IA","AI","intelligence artificielle","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Apprentissage automatique (machine learning)","text":"Une façon de faire apprendre à des ordinateurs des motifs à partir de beaucoup d'exemples, au lieu de leur donner des règles exactes.","also":["machine learning","ML","apprentissage machine","apprentissage statistique"]},{"id":"model","g":"ai","word":"Modèle","text":"Le « cerveau » entraîné d'un système d'IA, construit en apprenant à partir d'un très grand nombre d'exemples. Les modèles diffèrent par leurs capacités, leur vitesse et leur prix.","also":["modèles","modèle d'IA","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Grand modèle de langage (LLM)","text":"Un modèle d'IA entraîné sur d'énormes quantités de texte, qui peut donc lire et écrire du langage.","also":["LLM","LLMs","modèle de langage"]},{"id":"genai","g":"ai","word":"IA générative","text":"Une IA qui crée de nouvelles choses, comme du texte, des images ou du code, au lieu de seulement les trier ou les repérer.","also":["GenAI","IA générative","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot (agent conversationnel)","text":"Un programme avec lequel tu parles dans la langue de tous les jours, en écrivant ou en parlant.","also":["chatbots","agent conversationnel","robot de discussion"]},{"id":"prompt","g":"ai","word":"Prompt (consigne)","text":"Ce que tu donnes à une IA : ta question ou tes instructions, plus tout ce que tu lui fournis. Des prompts plus clairs donnent en général de meilleures réponses.","also":["prompts","consigne","requête","instruction"]},{"id":"prompteng","g":"ai","word":"Ingénierie de prompt","text":"L'art d'écrire des prompts qui donnent des résultats fiables et utiles.","also":["prompt engineering","rédaction de prompts"]},{"id":"sysprompt","g":"ai","word":"Prompt système","text":"Des instructions de fond qu'une IA reçoit avant le début de la conversation, qui fixent son rôle et ses règles. Elles comptent davantage que ce que tu tapes.","also":["prompts système","instructions système","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Contexte","text":"Tout ce que l'IA peut voir pendant qu'elle travaille : les instructions, tes messages, les fichiers qu'elle a lus et ses réponses précédentes.","noTip":1},{"id":"ctxwin","g":"ai","word":"Fenêtre de contexte","text":"Ce qu'une IA peut garder en tête en une fois, mesuré en tokens. Au-delà, les parties les plus anciennes sont oubliées ou résumées.","also":["fenêtres de contexte","context window","context windows"]},{"id":"session","g":"ai","word":"Session","text":"Une conversation de travail avec une IA, du début à la fin. Une nouvelle session démarre avec une mémoire vierge.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Mémoire","text":"Des notes qu'une IA garde d'une session à l'autre, pour se souvenir de tes préférences et de tes décisions passées.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"Quand une IA dit quelque chose avec aplomb alors que c'est inventé ou faux. Vérifie les faits importants.","also":["hallucinations","halluciner","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Entraînement","text":"Apprendre à un modèle en lui montrant un très grand nombre d'exemples, avant que quiconque ne l'utilise.","also":["entraîné","entraînement du modèle","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Données d'entraînement","text":"Les exemples à partir desquels un modèle a appris. Ses connaissances s'arrêtent à la date où ces données ont été collectées.","also":["jeu d'entraînement","training data","training set"]},{"id":"cutoff","g":"ai","word":"Date limite des connaissances","text":"La date où s'arrêtent les connaissances intégrées d'une IA. Elle ne saura rien de ce qui est arrivé après, sauf si elle va le chercher.","also":["date de coupure","knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Affinage (fine-tuning)","text":"Un entraînement supplémentaire d'un modèle existant sur tes propres exemples, pour le rendre meilleur dans une tâche précise.","also":["fine-tuning","ajustement fin","finetune","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inférence","text":"Le moment où un modèle d'IA est réellement utilisé pour répondre à quelque chose, par opposition à la phase où on l'entraîne.","also":["inference","inférence du modèle","model inference"]},{"id":"tooluse","g":"ai","word":"Utilisation d'outils","text":"Une IA qui peut agir, pas seulement parler : lancer des commandes, lire des fichiers ou chercher sur le web, grâce aux outils que l'appli lui donne.","also":["appel d'outils","appel d'outil","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Sous-agent","text":"Une IA auxiliaire à qui une IA principale confie un travail plus petit et dont elle récupère le résultat.","also":["sous-agents","subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agents","text":"Plusieurs IA qui travaillent ensemble sur un même travail, chacune avec sa part, comme une petite équipe.","also":["système multi-agents","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Ce qu'une IA a le droit de faire toute seule avant de devoir demander à une personne.","also":["autonome","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Humain dans la boucle","text":"Garder une personne impliquée pour vérifier ou approuver ce que fait l'IA aux moments clés. Dans AI-gile, c'est toi.","also":["human in the loop","human-in-the-loop","HITL","supervision humaine"]},{"id":"guardrails","g":"ai","word":"Garde-fous","text":"Des limites et des vérifications qui encadrent les actions d'une IA pour qu'elles restent sûres, comme exiger une approbation avant toute mise en ligne. Ils réduisent le risque d'erreurs, sans le supprimer.","also":["garde-fou","guardrails","guardrail","barrières de sécurité"]},{"id":"rag","g":"ai","word":"Génération augmentée par récupération (RAG)","text":"Laisser une IA chercher dans tes propres documents avant de répondre, pour que ses réponses reposent sur tes faits.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Plongement (embedding)","text":"Transformer un texte en une liste de nombres qui en capte le sens, pour qu'un ordinateur retrouve des choses qui veulent dire à peu près la même chose.","also":["embeddings","embedding","plongements","représentation vectorielle"]},{"id":"vectordb","g":"ai","word":"Base de données vectorielle","text":"Une base de données faite pour chercher dans ces listes de nombres (les embeddings), afin de trouver des contenus de sens proche.","also":["bases de données vectorielles","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Un standard commun pour brancher des outils et des sources de données sur des applis d'IA, pour qu'une IA puisse s'en servir.","also":["MCP","protocole de contexte de modèle"]},{"id":"temperature","g":"ai","word":"Température","text":"Un réglage qui dit à quel point les réponses d'une IA sont audacieuses. Basse, elle donne des réponses plus stables et prévisibles; haute, des réponses plus variées. Dans aucun des deux cas l'IA n'a toujours raison.","also":["température du modèle","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Capable de travailler avec plus d'un type d'information, comme le texte, les images et le son.","also":["multi-modal","multimodale"]},{"id":"evals","g":"ai","word":"Évaluation (eval)","text":"Un test planifié qui mesure la qualité du travail d'une IA sur des exemples choisis, pour comparer des modèles ou des prompts.","also":["eval","evals","évaluations"]},{"id":"bias","g":"ai","word":"Biais","text":"Quand une IA (ou une personne) penche injustement d'un côté, souvent à cause des exemples qui ont servi à son apprentissage.","also":["biaisé","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"IA responsable","text":"Utiliser l'IA de façon juste, sûre et honnête, en gardant des personnes responsables des résultats.","also":["IA éthique","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Injection de prompt","text":"Une ruse où des instructions cachées dans une page web ou un fichier essaient de faire faire à une IA quelque chose que son utilisateur n'a pas demandé.","also":["injections de prompt","prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limite de débit","text":"Un plafond au nombre de demandes que tu peux envoyer à un service en un temps donné. Si tu le dépasses, tu dois attendre.","also":["limites de débit","rate limit","rate limits","rate limited","limitation de débit"]},{"id":"usagelimit","g":"ai","word":"Limite d'utilisation","text":"La quantité de travail d'IA que ton forfait permet sur une période, après quoi il se met en pause ou coûte plus cher.","also":["limites d'utilisation","quota","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Construire un logiciel en décrivant surtout ce qu'on veut à une IA et en la laissant écrire le code.","also":["vibe-coding","programmation à l'ambiance"]},{"id":"budget","g":"money","word":"Budget","text":"La somme d'argent mise de côté pour quelque chose.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Estimation des coûts","text":"Ton meilleur pronostic sur ce que quelque chose va coûter, avant de commencer.","also":["estimations des coûts","devis estimatif","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Retour sur investissement (ROI)","text":"Ce que tu récupères par rapport à ce que tu as mis. S'il est positif, ça en valait la peine.","also":["ROI","RSI","retour sur investissement","return on investment"]},{"id":"tco","g":"money","word":"Coût total de possession (TCO)","text":"Tout ce que quelque chose coûte vraiment sur toute sa vie, pas seulement le prix d'achat : l'exploitation, le support, les mises à niveau et enfin le retrait.","also":["TCO","coût total","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx et OpEx (dépenses d'investissement et de fonctionnement)","text":"Le CapEx est l'argent dépensé d'avance pour des choses qu'on garde; l'OpEx est la dépense courante, comme les factures mensuelles.","also":["CapEx","OpEx","dépenses d'investissement","dépenses de fonctionnement","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abonnement","text":"Payer régulièrement, en général chaque mois ou chaque année, pour continuer à utiliser quelque chose.","also":["abonnements","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Logiciel en tant que service (SaaS)","text":"Un logiciel que tu utilises en ligne et que tu paies par abonnement, tandis que son créateur le fait tourner pour toi.","also":["SaaS","logiciel en ligne","software as a service"]},{"id":"payg","g":"money","word":"Paiement à l'usage","text":"Ne payer que ce que tu utilises, comme l'informatique en nuage ou les tokens d'IA.","also":["pay as you go","pay-as-you-go","facturation à l'usage","usage-based pricing"]},{"id":"overage","g":"money","word":"Dépassement","text":"Une utilisation au-delà de ce que comprend ton forfait, qui peut coûter un supplément.","also":["dépassements","frais de dépassement","overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Alerte de facturation","text":"Un message quand les dépenses ou l'utilisation atteignent un niveau que tu as choisi. Il t'avertit, mais n'empêche pas toujours de nouveaux frais.","also":["alertes de facturation","alerte de dépenses","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Offre gratuite","text":"Un niveau gratuit d'un service payant, avec des limites. Pratique pour débuter.","also":["formule gratuite","forfait gratuit","free tier","free plan"]},{"id":"pricing","g":"money","word":"Grille tarifaire","text":"Les différentes formules qu'un service vend, chacune avec son prix et ses limites.","also":["formules tarifaires","forfaits","tarifs","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"Les règles qui disent comment tu peux utiliser, copier, modifier ou partager quelque chose que quelqu'un d'autre a fait, comme un logiciel, des polices ou des images.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (code ouvert)","text":"Un logiciel dont le code peut être lu par tout le monde, utilisé et souvent modifié gratuitement, selon les règles de sa licence.","also":["open-source","logiciel libre","code ouvert","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licence open source","text":"Les règles qui accompagnent un code open source. Certaines permettent presque tout (comme MIT); d'autres demandent de partager aussi tes modifications (comme GPL).","also":["licences open source","licence libre","licence MIT","GPL","open source licence","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Propriétaire","text":"Qui appartient à une entreprise et ne peut pas être copié ou modifié librement. Le contraire de l'open source.","also":["logiciel propriétaire","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Droit d'auteur","text":"Le droit légal d'un créateur de contrôler les copies de son travail, y compris le code et les textes.","also":["copyright","protégé par le droit d'auteur","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Propriété intellectuelle (PI)","text":"Les idées et créations que la loi considère comme appartenant à quelqu'un, comme le code, les designs, les noms et les logos.","also":["PI","IP","propriété intellectuelle","intellectual property"]},{"id":"tos","g":"money","word":"Conditions d'utilisation","text":"Les règles que tu acceptes quand tu utilises un service.","also":["conditions générales","CGU","CGV","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contrat","text":"Un accord écrit entre deux parties que la loi fera respecter.","also":["contrats","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Cahier des charges (SOW)","text":"Un document qui fixe exactement quel travail sera fait, pour quand et pour combien.","also":["SOW","énoncé des travaux","statement of work"]},{"id":"fixedprice","g":"money","word":"Prix forfaitaire","text":"Un prix convenu pour tout le travail, quelle que soit sa durée.","also":["forfait","au forfait","prix fixe","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Régie (temps passé)","text":"Payer les heures réellement travaillées et les choses réellement utilisées, plutôt qu'un prix fixé.","also":["T&M","en régie","time and materials","temps et matériel"]},{"id":"invoice","g":"money","word":"Facture","text":"Un document qui demande le paiement d'un travail fait ou de biens fournis.","also":["factures","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Dépendance à un fournisseur (lock-in)","text":"Quand quitter un fournisseur est si difficile ou si coûteux que tu n'as plus d'autre choix que de rester chez lui.","also":["enfermement propriétaire","lock-in","vendor lock-in","verrouillage fournisseur"]},{"id":"procurement","g":"money","word":"Achats","text":"Le processus qui consiste à choisir des fournisseurs et à leur acheter.","also":["approvisionnement","procurement","passation de marchés"]},{"id":"servicecredit","g":"money","word":"Avoir de service","text":"De l'argent rendu ou une remise que tu obtiens quand un fournisseur ne respecte pas son SLA.","also":["avoirs de service","crédit de service","service credit","service credits","pénalités SLA"]}]}};
